import { Rate, Trend } from 'k6/metrics';

// 1. CONFIGURATION: Parameterized via ENV (Injected by CI)
const TARGET_HOST = __ENV.TARGET_HOST || 'localhost';
const BACKEND_PORT = __ENV.BACKEND_PORT || '3000';
const BASE_URL = `http://${TARGET_HOST}:${BACKEND_PORT}`;

// 2. THRESHOLDS: Gate Release (Acceptance Criteria: ≤150ms avg)
export const options = {
  stages: [
    { duration: '30s', target: 50 },  // Ramp up
    { duration: '1m', target: 100 },  // Sustained Load
    { duration: '30s', target: 0 },   // Ramp down
  ],
  thresholds: {
    // Global HTTP Request Duration
    'http_req_duration': ['avg<150', 'p(95)<300'], 
    // Custom Metric: Order Propagation Latency
    'order_propagation_latency': ['avg<150', 'p(95)<300'],
    // Error Rate
    'http_req_failed': ['rate<0.01'], // <1% errors
  },
  // Discard response bodies to save memory unless debugging
  discardResponseBodies: true, 
};

// 3. CUSTOM METRICS
const propagationLatency = new Trend('order_propagation_latency');
const errorRate = new Rate('order_propagation_errors');

// 4. TEST DATA FACTORY (Deterministic, No External Deps)
function generateOrderPayload() {
  return JSON.stringify({
    id: `order_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    tableId: `table_${Math.floor(Math.random() * 20) + 1}`,
    items: [
      { menuItemId: 'item_burger', quantity: 1, modifiers: ['no_pickles'] },
      { menuItemId: 'item_fries', quantity: 1, modifiers: [] },
    ],
    timestamp: new Date().toISOString(),
  });
}

const params = {
  headers: {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
    // Add Auth header if required: 'Authorization': `Bearer ${__ENV.API_TOKEN}`
  },
  timeout: '10s', // k6 timeout for request
};

export default function () {
  const payload = generateOrderPayload();
  const url = `${BASE_URL}/api/orders`; // Assumes REST endpoint

  // 5. EXECUTION: Measure Round-trip (POS -> Backend -> KDS WebSocket Push Simulation)
  // Note: k6 does not natively support WebSocket server-push measurement easily in HTTP mode.
  // This script validates the INGESTION latency (POS -> Backend Ack). 
  // KDS Sync validation requires a separate WS client or backend metric exposure.
  const startTime = new Date();
  const res = http.post(url, payload, params);
  const endTime = new Date();
  const latency = endTime - startTime;

  // 6. ASSERTIONS & METRICS
  const success = check(res, {
    'status is 201': (r) => r.status === 201,
    'response has orderId': (r) => r.json('id') !== undefined,
    'latency < 500ms': () => latency < 500, // Hard sanity check
  });

