// src/types.ts
export enum OrderPriority {
  LOW = "low",
  MEDIUM = "medium",
  HIGH = "high",
  CRITICAL = "critical",
}

export interface OrderItem {
  id: string;
  name: string;
  quantity: number;
  /** prep time in minutes */
  prepTimeMinutes: number;
}

export interface Order {
  id: string;
  tableNumber: number;
  items: OrderItem[];
  priority: OrderPriority;
  /** ISO‑8601 timestamp when the order was placed */
  placedAt: string;
  /** current status as known by the POS */
  status: "pending" | "held" | "ready" | "cancelled";
  /** estimated total prep time (sum of item prep times) */
  estimatedPrepTimeMinutes: number;
}

/** Message shape received from the WebSocket server */
export interface OrderUpdate {
  type: "created" | "updated" | "deleted";
  payload: Order | null; // null for deleted events
}

/** Action shape for the reducer */
export type OrdersAction =
  | { type: "SET_ORDERS"; payload: Order[] }
  | { type: "ADD_ORDER"; payload: Order }
  | { type: "UPDATE_ORDER"; payload: Partial<Order> & Pick<Order, "id"> }
  | { type: "REMOVE_ORDER"; payload: string };
