## 3. Reducer (`src/reducers/ordersReducer.ts`)

```typescript
// src/reducers/ordersReducer.ts
import { OrdersAction, Order } from "../types";

export const ordersReducer = (
  state: Order[] = [],
  action: OrdersAction
): Order[] => {
  switch (action.type) {
    case "SET_ORDERS":
      return [...action.payload];
    case "ADD_ORDER":
      // avoid duplicates
      if (state.some((o) => o.id === action.payload.id)) return state;
      return [...state, action.payload];
    case "UPDATE_ORDER":
      return state.map((order) =>
        order.id === action.payload.id ? { ...order, ...action.payload } : order
      );
    case "REMOVE_ORDER":
      return state.filter((order) => order.id !== action.payload);
    default:
      return state;
  }
};
```

