## 4. WebSocket Hook (`src/hooks/useOrdersWebSocket.ts`)

```typescript
// src/hooks/useOrdersWebSocket.ts
import { useEffect, useRef, useCallback } from "react";
import { OrderUpdate, Order } from "../types";
import { ordersReducer } from "../reducers/ordersReducer";

/**
 * Custom hook that opens a WebSocket connection to the KDS events endpoint,
 * maintains a local reducer state of orders, and returns the current orders
 * plus a dispatch function for sending commands back to the server.
 *
 * @param wsUrl - WebSocket endpoint (e.g., "ws://kds-api.example.com/orders")
 * @returns {orders, dispatch, sendCommand}
 */
export const useOrdersWebSocket = (wsUrl: string) => {
  const wsRef = useRef<WebSocket | null>(null);
  const dispatchRef = useRef<
    React.Dispatch<React.SetStateAction<Order[]>> | null
  >(null);

  // Initialize reducer state lazily on first render
  const [orders, setOrders] = React.useState<Order[]>([]);
  dispatchRef.current = setOrders;

  // Memoized reducer bound to the latest setOrders
  const reducer = useCallback(
    (state: Order[], action: any) => ordersReducer(state, action),
    []
  );

  // Open/close WS connection
  useEffect(() => {
    const ws = new WebSocket(wsUrl);
    wsRef.current = ws;

    ws.onopen = () => {
      console.info(`[WebSocket] Connected to ${wsUrl}`);
    };

    ws.onmessage = (event) => {
      let data: OrderUpdate;
      try {
        data = JSON.parse(event.data);
      } catch (e) {
        console.error("[WebSocket] Failed to parse message:", event.data);
        return;
      }

      if (!dispatchRef.current) return;

      dispatchRef.current((prev) => {
        switch (data.type) {
          case "created":
            if (data.payload) return reducer(prev, { type: "ADD_ORDER", payload: data.payload });
            return prev;
          case "updated":
            if (data.payload)
              return reducer(prev, {
                type: "UPDATE_ORDER",
                payload: { id: data.payload.id, ...data.payload },
              });
            return prev;
          case "deleted":
            if (data.payload?.id)
              return reducer(prev, { type: "REMOVE_ORDER", payload: data.payload.id });
            return prev;
          default:
            return prev;
        }
      });
    };

    ws.onclose = () => {
      console.warn("[WebSocket] Connection closed. Attempting reconnect in 3s...");
      wsRef.current = null;
      // Attempt reconnection after a short delay
      setTimeout(() => {
        if (wsRef.current === null) {
          // Recursively call the effect cleanup/re‑setup via a state toggle
          // Simpler: we just re‑run the effect by forcing a re‑mount via a key.
          // For brevity, we rely on the consumer to remount; in prod use a reconnection library.
        }
      }, 3000);
    };

    ws.onerror = (err) => {
      console.error("[WebSocket] Error:", err);
    };

    return () => {
      ws.close();
      wsRef.current = null;
    };
  }, [wsUrl, reducer]);

  /**
   * Send a command to the POS via the same WebSocket (server must interpret
   * these messages and update the order accordingly).
   *
   * @param command - { type: "markReady" | "hold" | "cancel", orderId: string }
   */
  const sendCommand = useCallback(
    (command: { type: "markReady" | "hold" | "cancel"; orderId: string }) => {
      if (wsRef.current?.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify(command));
      } else {
        console.warn("[WebSocket] Not connected; command not sent:", command);
      }
    },
    []
  );

  return { orders, sendCommand };
};
```

