            className="btn btn-hold"
            onClick={() => onHold(order.id)}
            disabled={order.status === "held"}
          >
            Hold
          </button>
          <button
            className="btn btn-cancel"
            onClick={() => onCancel(order.id)}
            disabled={order.status === "cancelled"}
          >
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
