    COMPLETED: '#9E9E9E',
  };

  const getStationIcon = (station: OrderItem['station']) => {
    switch (station) {
      case 'GRILL': return <Kitchen fontSize="small" />;
      case 'FRYER': return <LocalShipping fontSize="small" />;
      case 'SALAD': return <Restaurant fontSize="small" />;
      case 'DESSERT': return <DirectionsCar fontSize="small" />;
      case 'BAR': return <Person fontSize="small" />;
      default: return <Visibility fontSize="small" />;
    }
  };

  const getOrderTypeBadge = (type: KDSOrder['orderType']) => {
    switch (type) {
      case 'DINE_IN': return <Chip label="DINE_IN" sx={{ bgcolor: '#2196F3', color: 'white' }} size="small" />;
      case 'TAKEOUT': return <Chip label="TAKEOUT" sx={{ bgcolor: '#FF9800', color: 'white' }} size="small" />;
      case 'DELIVERY': return <Chip label="DELIVERY" sx={{ bgcolor: '#4CAF50', color: 'white' }} size="small" />;
      case 'DRIVE_THRU': return <Chip label="DRIVE_THRU" sx={{ bgcolor: '#9C27B0', color: 'white' }} size="small" />;
      default: return null;
    }
  };

  const timerText = useMemo(() => {
    if (order.estimatedReadyAt) {
      const target = new Date(order.estimatedReadyAt);
      const now = new Date();
      const diffMs = target.getTime() - now.getTime();
      if (diffMs <= 0) return 'OVERDUE';
      const minutes = Math.ceil(diffMs / (1000 * 60));
      return `${minutes} min`;
    }
    const created = new Date(order.createdAt);
    const now = new Date();
    const diffMs = now.getTime() - created.getTime();
    const minutes = Math.floor(diffMs / (1000 * 60));
    return `${minutes} min`;
  }, [order.estimatedReadyAt, order.createdAt]);

  const handleAction = (action: KDSCommandPayload['action'], itemIds?: string[]) => {
    onAction(action, itemIds);
  };

  return (
    <Card
      sx={{
        borderLeft: `4px solid ${priorityColors[order.priority]}`,
