// src/types/kds.ts
export type OrderStatus = 'PENDING' | 'PREPARING' | 'READY' | 'HELD' | 'CANCELLED' | 'COMPLETED';
export type OrderPriority = 'LOW' | 'NORMAL' | 'HIGH' | 'URGENT';

export interface OrderItem {
  id: string;
  name: string;
  quantity: number;
  modifiers: string[];
  station: 'GRILL' | 'FRYER' | 'SALAD' | 'DESSERT' | 'BAR';
  prepTimeSeconds: number;
