  createdAt: string;
  updatedAt: string;
  estimatedReadyAt?: string;
  totalPrepTimeSeconds: number;
  source: 'POS' | 'KIOSK' | 'MOBILE';
}

export interface KDSCommandPayload {
  orderId: string;
  action: 'START' | 'HOLD' | 'MARK_READY' | 'CANCEL' | 'RECALL' | 'BUMP';
  itemIds?: string[];
  userId: string;
  timestamp: string;
}

export interface WebSocketMessage<T = unknown> {
  event: 'ORDER_CREATED' | 'ORDER_UPDATED' | 'ORDER_DELETED' | 'STATUS_CHANGED' | 'HEARTBEAT' | 'SYNC_COMPLETE';
  payload: T;
  timestamp: string;
}
