// src/components/OrderCard.tsx
import { memo, useMemo } from 'react';
import { 
  Card, CardContent, CardHeader, CardActions, 
  Typography, Chip, IconButton, Box, Stack, Divider, 
  Tooltip, Badge, Alert, Button, Menu, MenuItem 
} from '@mui/material';
import { 
  Timer, PriorityHigh, Warning, CheckCircle, PauseCircle, 
  PlayCircle, Cancel, Restaurant, LocalShipping, DirectionsCar, 
  Person, Kitchen, Visibility, MoreVert 
} from '@mui/icons-material';
import { formatDistanceToNow, parseISO, differenceInSeconds } from 'date-fns';
import { clsx } from 'clsx';
import { KDSOrder, OrderStatus, OrderPriority, OrderItem } from '../types/kds';

interface OrderCardProps {
  order: KDSOrder;
  onAction: (action: KDSCommandPayload['action'], itemIds?: string[]) => void;
  compact?: boolean;
}

const OrderCard = memo(({ order, onAction, compact = false }: OrderCardProps) => {
  const statusColor = useMemo(() => {
    switch (order.status) {
      case 'PENDING': return 'warning.main';
      case 'PREPARING': return 'info.main';
      case 'READY': return 'success.main';
      case 'HELD': return 'error.main';
      default: return 'grey.main';
    }
  }, [order.status]);

  const priorityColor = useMemo(() => {
    switch (order.priority) {
      case 'URGENT': return 'error.main';
      case 'HIGH': return 'warning.main';
      case 'NORMAL': return 'info.main';
      case 'LOW': return 'grey.main';
      default: return 'grey.main';
    }
  }, [order.priority]);

  const orderTypeIcon = useMemo(() => {
    switch (order.orderType) {
      case 'DINE_IN': return <Restaurant />;
      case 'TAKEOUT': return <LocalShipping />;
      case 'DELIVERY': return <DirectionsCar />;
      case 'DRIVE_THRU': return <Person />;
      default: return <Kitchen />;
    }
  }, [order.orderType]);

  const timerText = useMemo(() => {
    if (order.estimatedReadyAt) {
      const target = new Date(order.estimatedReadyAt);
      const now = new Date();
      const diffMs = target.getTime() - now.getTime();
      if (diffMs <= 0) return 'OVERDUE';
      const mins = Math.ceil(diffMs / 60000);
      return `${mins} min`;
    }
    const created = new Date(order.createdAt);
    const now = new Date();
    const diffMs = now.getTime() - created.getTime();
    const mins = Math.floor(diffMs / 60000);
    return `${mins} min`;
  }, [order.estimatedReadyAt, order.createdAt]);

  const handleAction = (action: KDSCommandPayload['action'], itemIds?: string[]) => {
    onAction(action, itemIds);
  };

  const getItemStatusBadge = (item: OrderItem) => {
    switch (item.status) {
      case 'PENDING': return <Chip label="Pending" size="small" color="error" />;
      case 'PREPARING': return <Chip label="Preparing" size="small" color="warning" />;
      case 'READY': return <Chip label="Ready" size="small" color="success" />;
      case 'HELD': return <Chip label="Held" size="small" color="info" />;
      default: return <Chip label="Unknown" size="small" />;
    }
  };

  return (
    <Card 
      variant="outlined" 
      sx={{
        borderLeft: `4px solid ${priorityColor}`,
        borderRadius: 2,
        marginBottom: compact ? 1 : 2,
        position: 'relative'
      }}
    >
      {!compact && (
        <Box sx={{ position: 'absolute', top: 4, right: 4 }}>
          <Badge badgeContent={order.priority} color="error" invisible={order.priority !== 'URGENT'}>
            <PriorityHigh fontSize="small" color="error" />
          </Badge>
        </Box>
      )}
      <CardHeader
        title={
          <Typography variant="h6" component="span" sx={{ flexGrow: 1 }}>
            {order.posOrderId}
          </Typography>
        }
        subheader={
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Tooltip title={order.orderType}>
              {orderTypeIcon}
            </Tooltip>
            {order.tableNumber && (
              <Typography variant="body2" color="text.secondary">
                Table {order.tableNumber}
              </Typography>
            )}
          </Box>
        }
        action={
          <IconButton aria-label="more" onClick={() => {}}>
            <MoreVert />
          </IconButton>
        }
      />
      <Divider sx={{ my: 1.5 }} />
      <CardContent>
        <Stack spacing={1}>
          {order.items.map((item) => (
            <Box key={item.id} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Typography variant="body2" sx={{ flexGrow: 1 }}>
                {item.name} x{item.quantity}
              </Typography>
              {item.modifiers.length > 0 && (
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                  {item.modifiers.map((mod) => (
                    <Chip key={mod} label={mod} size="small" sx={{ fontSize: 0.8 }} />
                  ))}
                </Box>
              )}
              <Box sx={{ ml: 2 }}>
                {getItemStatusBadge(item)}
              </Box>
            </Box>
          ))}
        </Stack>
      </CardContent>
      <CardActions sx={{ justifyContent: 'flex-end' }}>
        {order.status === 'PENDING' && (
          <>
            <Button 
              size="small" 
              variant="contained" 
              color="primary" 
              onClick={() => handleAction('START')}
              sx={{ mr: 1 }}
            >
              Start Prep
            </Button>
            <Button 
              size="small" 
              variant="outlined" 
              onClick={() => handleAction('HOLD')}
            >
              Hold
            </Button>
          </>
        )}
        {order.status === 'PREPARING' && (
          <>
            <Button 
              size="small" 
              variant="contained" 
              color="success" 
              onClick={() => handleAction('MARK_READY')}
              sx={{ mr: 1 }}
            >
              Mark Ready
            </Button>
            <Button 
              size="small" 
              variant="outlined" 
              onClick={() => handleAction('HOLD')}
            >
              Hold
            </Button>
          </>
        )}
        {order.status === 'READY' && (
          <>
            <Button 
              size="small" 
              variant="contained" 
              color="success" 
              onClick={() => handleAction('COMPLETED')}
              sx={{ mr: 1 }}
            >
              Complete
            </Button>
            <Button 
              size="small" 
              variant="outlined" 
              onClick={() => handleAction('RECALL')}
            >
              Recall
            </Button>
          </>
        )}
        {order.status === 'HELD' && (
          <>
            <Button 
              size="small" 
              variant="contained" 
              color="primary" 
              onClick={() => handleAction('RESUME')}
              sx={{ mr: 1 }}
            >
              Resume
            </Button>
            <Button 
              size="small" 
              variant="outlined" 
              color="error" 
              onClick={() => handleAction('CANCEL')}
            >
              Cancel
            </Button>
          </>
        )}
        {!['COMPLETED', 'CANCELLED'].includes(order.status) && (
          <Button 
            size="small" 
            variant="outlined" 
            color="error" 
            onClick={() => handleAction('CANCEL')}
          >
            Cancel
          </Button>
        )}
      </CardActions>
      {order.status === 'HELD' && (
        <Alert severity="info" sx={{ mt: 1, px: 1 }}>
          Order is currently on hold
        </Alert>
      )}
    </Card>
  );
});

export default OrderCard;
