};

interface MenuAnchorProps {
  children: React.ReactNode;
}

const MenuAnchor = ({ children }: MenuAnchorProps) => {
  const [anchorEl, setAnchorEl] = React.useState<null | HTMLElement>(null);

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  return (
    <>
      <Button onClick={handleClick} aria-controls="menu-list" aria-haspopup="true">
        {children}
      </Button>
      <Menu 
        id="menu-list"
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleClose}
        MenuListProps={{
          'aria-labelledby': 'menu-list'
        }}
      >
        {React.Children.map(children, child => 
          React.isValidElement(child) && child.type === MenuItem 
            ? React.cloneElement(child, { onClick: handleClose })
            : child
        )}
      </Menu>
    </>
  );
};
