## 5. Main Board Page (`src/pages/KDSBoard.tsx`)
```typescript
// src/pages/KDSBoard.tsx
import { useState } from 'react';
import { useOrdersWebSocket } from '../hooks/useOrdersWebSocket';
import { KDSHeader } from '../components/KDSHeader';
import { OrderCard } from '../components/OrderCard';
import { Box, Typography, CircularProgress, Alert } from '@mui/material';
import { useStationFilter } from '../hooks/useStationFilter';
import { useEffect } from 'react';

const KDSBoard = () => {
  const { orders, ordersList, connectionStatus, sendCommand } = useOrdersWebSocket();
  const { stationFilters, setStationFilters } = useStationFilter();
  const [filteredOrders, setFilteredOrders] = useState<Array<typeof ordersList.value>>(ordersList);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (stationFilters.length === 0) {
      setFilteredOrders(ordersList);
    } else {
      setFilteredOrders(
        ordersList.filter(order => 
          order.items.some(item => stationFilters.includes(item.station))
        )
      );
    }
  }, [ordersList, stationFilters]);

  const handleAction = async (action: string, itemIds?: string[]) => {
    try {
      // In a real implementation, we'd get the orderId from context
      // For demo, we'll use first order's ID - in practice this would be passed from OrderCard
      const orderId = filteredOrders[0]?.id || '';
      if (!orderId) throw new Error('No order selected');

      await sendCommand({
        orderId,
        action: action as any,
        itemIds,
        userId: 'kitchen-staff-1', // Would come from auth
        timestamp: new Date().toISOString()
      });
    } catch (err) {
      setError('Failed to execute action. Please try again.');
      console.error(err);
    }
  };

  if (connectionStatus === 'CONNECTING') {
    return (
      <Box sx={{ p: 4, textAlign: 'center' }}>
        <Typography variant="h5">Connecting to Kitchen System...</Typography>
        <CircularProgress size={48} />
      </Box>
    );
  }

  if (connectionStatus === 'ERROR') {
    return (
      <Box sx={{ p: 4, textAlign: 'center' }}>
        <Typography variant="h5" color="error">
          Connection Error
        </Typography>
        <Button variant="contained" onClick={() => window.location.reload()}>
          Retry Connection
        </Button>
      </Box>
    );
  }

  const orderCounts = ordersList.reduce((acc, order) => {
    acc[order.status] = (acc[order.status] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  return (
    <Box sx={{ p: 3 }}>
      <KDSHeader 
        connectionStatus={connectionStatus} 
        orderCounts={orderCounts} 
      />
      <Box sx={{ mt: 3, minHeight: 'calc(100vh - 200px)' }}>
        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}
        {filteredOrders.length === 0 ? (
          <Box sx={{ textAlign: 'center', py: 4 }}>
            <Typography variant="body2">
              No orders match current filters
            </Typography>
            {stationFilters.length > 0 && (
              <Button 
                variant="outlined" 
                size="small" 
                onClick={() => setStationFilters([])}
              >
                Clear Filters
              </Button>
            )}
          </Box>
        ) : (
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2, overflowY: 'auto' }}>
            {filteredOrders.map(order => (
              <Box 
                key={order.id} 
                sx={{ 
                  width: { xs: '100%', sm: '48%', md: '30%', lg: '22%' }, 
                  minWidth: 200 
                }}
              >
                <OrderCard 
                  order={order} 
                  onAction={handleAction} 
                  compact={window.innerWidth < 600} 
                />
              </Box>
            ))}
          </Box>
        )}
      </Box>
    </Box>
  );
};

export default KDSBoard;
