```typescript
// src/hooks/__tests__/useOrdersWebSocket.test.tsx
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, waitFor, act } from '@testing-library/react';
import { useOrdersWebSocket } from '../useOrdersWebSocket';
import { KDSOrder } from '../../types/kds';
import { mockSocketIoClient, getMockSocket } from './mocks/socket';

// Setup mock
mockSocketIoClient();

const createMockOrder = (overrides: Partial<KDSOrder> = {}): KDSOrder => ({
  id: 'order-1',
  posOrderId: 'ORD-001',
  status: 'PENDING',
  priority: 'NORMAL',
  orderType: 'DINE_IN',
  items: [{ 
    id: 'item-1', 
    name: 'Burger', 
    quantity: 1, 
    modifiers: [], 
    station: 'GRILL', 
    prepTimeSeconds: 300,
    status: 'PENDING'
  }],
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  totalPrepTimeSeconds: 300,
  source: 'POS',
  ...overrides,
});

describe('useOrdersWebSocket', () => {
  let mockSocket: ReturnType<typeof getMockSocket>;

  beforeEach(() => {
    vi.useFakeTimers();
    renderHook(() => useOrdersWebSocket());
    mockSocket = getMockSocket()!;
    expect(mockSocket).toBeDefined();
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.clearAllMocks();
  });

  it('should initialize with empty orders and CONNECTING status', () => {
    const { result } = renderHook(() => useOrdersWebSocket());
    expect(result.current.orders.size).toBe(0);
    expect(result.current.ordersList).toEqual([]);
    expect(result.current.connectionStatus).toBe('CONNECTING');
  });

  it('should transition to CONNECTED on socket connect', () => {
    const { result } = renderHook(() => useOrdersWebSocket());

    act(() => {
      mockSocket.emit('connect');
    });

    expect(result.current.connectionStatus).toBe('CONNECTED');
  });

  it('should add order on ORDER_CREATED event', () => {
    const { result } = renderHook(() => useOrdersWebSocket());
    const newOrder = createMockOrder({ id: 'order-new', posOrderId: 'ORD-002' });

    act(() => {
      mockSocket.emit('connect');
      mockSocket.emit('ORDER_CREATED', newOrder);
    });

    expect(result.current.orders.size).toBe(1);
    expect(result.current.orders.has('order-new')).toBe(true);
    expect(result.current.ordersList).toHaveLength(1);
    expect(result.current.ordersList[0]).toEqual(newOrder);
  });

  it('should update order on ORDER_UPDATED event', () => {
    const { result } = renderHook(() => useOrdersWebSocket());
    const initialOrder = createMockOrder({ id: 'order-1', status: 'PENDING' });
    const updatedOrder = createMockOrder({ 
      id: 'order-1', 
      status: 'PREPARING', 
      updatedAt: new Date().toISOString() 
    });

    act(() => {
      mockSocket.emit('connect');
      mockSocket.emit('ORDER_CREATED', initialOrder);
    });
    expect(result.current.orders.get('order-1')?.status).toBe('PENDING');

    act(() => {
      mockSocket.emit('ORDER_UPDATED', updatedOrder);
    });

    expect(result.current.orders.get('order-1')?.status).toBe('PREPARING');
    expect(result.current.ordersList[0].status).toBe('PREPARING');
  });

  it('should remove order on ORDER_DELETED event', () => {
    const { result } = renderHook(() => useOrdersWebSocket());
    const order = createMockOrder({ id: 'order-1' });

    act(() => {
      mockSocket.emit('connect');
      mockSocket.emit('ORDER_CREATED', order);
    });
    expect(result.current.orders.size).toBe(1);

    act(() => {
      mockSocket.emit('ORDER_DELETED', 'order-1');
    });

    expect(result.current.orders.size).toBe(0);
    expect(result.current.ordersList).toHaveLength(0);
  });

  it('should handle connection errors', () => {
    const { result } = renderHook(() => useOrdersWebSocket());

    act(() => {
      mockSocket.emit('connect_error', new Error('Failed to connect'));
    });

    expect(result.current.connectionStatus).toBe('ERROR');
  });

  it('should send command via sendCommand', async () => {
    const { result } = renderHook(() => useOrdersWebSocket());
    const mockCommand = {
      orderId: 'test-order',
      action: 'START',
      userId: 'test-user',
      timestamp: new Date().toISOString()
    };

    // Mock the API call
    vi.spyOn(result.current, 'sendCommand').mockImplementation(async () => {
      mockSocket.emit('COMMAND_SENT', mockCommand);
    });

    await act(async () => {
      await result.current.sendCommand(mockCommand);
    });

    expect(result.current.sendCommand).toHaveBeenCalledWith(mockCommand);
    expect(mockSocket.emit).toHaveBeenCalledWith('COMMAND_SENT', mockCommand);
  });
