### 2. Fixed WebSocket Hook (`src/hooks/useOrdersWebSocket.ts`)
```typescript
// src/hooks/useOrdersWebSocket.ts
import { useEffect, useRef, useCallback, useState, useMemo } from 'react';
import { io, Socket } from 'socket.io-client';
import { KDSOrder, KDSCommandPayload, WebSocketMessage, OrderStatus } from '../types/kds';
import { useAuthStore } from '../stores/authStore';
import { apiClient } from '../lib/apiClient';

export interface UseOrdersWebSocketReturn {
  orders: Map<string, KDSOrder>;
  ordersList: KDSOrder[];
  connectionStatus: 'CONNECTING' | 'CONNECTED' | 'DISCONNECTED' | 'ERROR';
  sendCommand: (payload: KDSCommandPayload) => Promise<void>;
  reconnect: () => void;
}

export const useOrdersWebSocket = (): UseOrdersWebSocketReturn => {
  const { token } = useAuthStore();
  const socketRef = useRef<Socket | null>(null);
  const [ordersMap, setOrdersMap] = useState<Map<string, KDSOrder>>(new Map());
  const [connectionStatus, setConnectionStatus] = useState<'CONNECTING' | 'CONNECTED' | 'DISCONNECTED' | 'ERROR'>('CONNECTING');

  // Derive sorted list for rendering
  const ordersList = useMemo(() => {
    const ordersArray = Array.from(ordersMap.values());
    return ordersArray.sort((a, b) => {
      // Priority: URGENT > HIGH > NORMAL > LOW
      const priorityOrder: Record<OrderPriority, number> = {
        URGENT: 4, HIGH: 3, NORMAL: 2, LOW: 1
      };
      const priorityDiff = priorityOrder[b.priority] - priorityOrder[a.priority];
      if (priorityDiff !== 0) return priorityDiff;

      // Then by age (oldest first)
      return new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
    });
  }, [ordersMap]);

  const connectSocket = useCallback(() => {
    if (!token) {
      setConnectionStatus('ERROR');
      return;
    }

    setConnectionStatus('CONNECTING');
    const socket = io(import.meta.env.VITE_API_URL, {
      auth: { token },
      transports: ['websocket'],
    });

    socketRef.current = socket;

    socket.on('connect', () => {
      setConnectionStatus('CONNECTED');
    });

    socket.on('disconnect', (reason) => {
      setConnectionStatus(reason === 'io server disconnect' ? 'DISCONNECTED' : 'ERROR');
    });

    socket.on('connect_error', (error) => {
      setConnectionStatus('ERROR');
      console.error('WebSocket connection error:', error);
    });

    // Handle order events
    socket.on('ORDER_CREATED', (order: KDSOrder) => {
      setOrdersMap(prev => new Map(prev).set(order.id, order));
    });

    socket.on('ORDER_UPDATED', (order: KDSOrder) => {
      setOrdersMap(prev => {
        const newMap = new Map(prev);
        newMap.set(order.id, order);
        return newMap;
      });
    });

    socket.on('ORDER_DELETED', (orderId: string) => {
      setOrdersMap(prev => {
        const newMap = new Map(prev);
        newMap.delete(orderId);
        return newMap;
      });
    });

    socket.on('STATUS_CHANGED', ({ orderId, status }: { orderId: string; status: OrderStatus }) => {
      setOrdersMap(prev => {
        const order = prev.get(orderId);
        if (!order) return prev;
        const updatedOrder = { ...order, status, updatedAt: new Date().toISOString() };
        const newMap = new Map(prev);
        newMap.set(orderId, updatedOrder);
        return newMap;
      });
    });

    return () => {
      socket.disconnect();
      socketRef.current = null;
    };
  }, [token]);

  useEffect(() => {
    return connectSocket();
  }, [connectSocket]);

  const sendCommand = useCallback(async (payload: KDSCommandPayload) => {
    if (!socketRef.current?.connected) {
      throw new Error('WebSocket not connected');
    }

    try {
      await apiClient.post('/kds/command', payload);
      // Optimistic update handled via WebSocket events from server
    } catch (error) {
      console.error('Failed to send command:', error);
      throw error;
    }
  }, []);

  const reconnect = useCallback(() => {
    socketRef.current?.disconnect();
    connectSocket();
  }, [connectSocket]);

  return {
    orders: ordersMap,
    ordersList,
    connectionStatus,
    sendCommand,
    reconnect
  };
};
```

