interface OrderCardProps {
  order: KDSOrder;
  onAction: (action: KDSCommandPayload['action'], itemIds?: string[]) => void;
  compact?: boolean;
}

const StationIconMap: Record<OrderItem['station'], React.ComponentType<any>> = {
  GRILL: Kitchen,
  FRYER: LocalShipping,
  SALAD: Restaurant,
  DESSERT: DirectionsCar,
  BAR: LocalShipping
};

const PriorityColorMap: Record<OrderPriority, string> = {
  URGENT: '#ef4444',
  HIGH: '#f97316',
  NORMAL: '#3b82f6',
  LOW: '#6b7280'
};

const StatusBadgeMap: Record<OrderStatus, { color: string; label: string }> = {
  PENDING: { color: 'warning', label: 'Pending' },
  PREPARING: { color: 'info', label: 'Preparing' },
  READY: { color: 'success', label: 'Ready' },
  HELD: { color: 'error', label: 'Held' },
  CANCELLED: { color: 'default', label: 'Cancelled' },
  COMPLETED: { color: 'success', label: 'Completed' }
};

const OrderCard = memo(({ order, onAction, compact = false }: OrderCardProps) => {
  const priorityColor = PriorityColorMap[order.priority];
  const statusInfo = StatusBadgeMap[order.status];

  const getItemStatus = (item: OrderItem): OrderStatus => {
    if (item.completedAt) return 'COMPLETED';
    if (item.startedAt) return 'PREPARING';
    return 'PENDING';
  };

  const getTimerDisplay = () => {
    if (order.estimatedReadyAt) {
      const readyTime = parseISO(order.estimatedReadyAt);
      const now = new Date();
      const isLate = readyTime < now;

      if (isLate) {
        return {
          text: `Ready ${formatDistanceToNow(readyTime, { addSuffix: false })} ago`,
          variant: 'error'
        };
      }
      return {
        text: `Ready in ${formatDistanceToNow(readyTime)}`,
        variant: 'success'
      };
    }

    const createdTime = parseISO(order.createdAt);
    return {
      text: `Elapsed: ${formatDistanceToNow(createdTime)}`,
      variant: 'info'
    };
  };

  const timerDisplay = getTimerDisplay();

  const handleAction = (action: KDSCommandPayload['action'], itemIds?: string[]) => {
    onAction(action, itemIds);
  };

  const getActionButtons = () => {
    switch (order.status) {
      case 'PREPARING':
        const incompleteItems = order.items.filter(item => !item.completedAt);
        const allItemsIncomplete = incompleteItems.length === order.items.length;
        const someItemsComplete = incompleteItems.length > 0 && incompleteItems.length < order.items.length;

        if (allItemsIncomplete) {
          return [
            <Button 
              key="start" 
              variant="contained" 
              color="primary" 
              size="small"
              onClick={() => handleAction('START')}
            >
              Start Prep
            </Button>,
            <Button 
              key="hold" 
              variant="outlined" 
              color="secondary" 
              size="small"
              onClick={() => handleAction('HOLD')}
            >
              Hold
            </Button>
          ];
        }

        if (someItemsComplete) {
          const readyItemIds = order.items
            .filter(item => item.completedAt)
            .map(item => item.id);

          return [
            <Button 
              key="mark-ready" 
              variant="contained" 
              color="success" 
              size="small"
              onClick={() => handleAction('MARK_READY', readyItemIds)}
            >
              Mark Items Ready
            </Button>,
            <Button 
              key="hold" 
              variant="outlined" 
              color="secondary" 
              size="small"
              onClick={() => handleAction('HOLD')}
            >
              Hold
            </Button>
          ];
        }
        break;

      case 'READY':
        return [
          <Button 
            key="complete" 
            variant="contained" 
            color="success" 
            size="small"
            onClick={() => handleAction('MARK_READY')}
          >
            Complete/Handoff
          </Button>,
          <Button 
            key="recall" 
            variant="text" 
            color="error" 
            size="small"
            onClick={() => handleAction('RECALL')}
          >
            Recall
          </Button>
        ];

      case 'HELD':
        return [
          <Button 
            key="resume" 
            variant="contained" 
            color="primary" 
            size="small"
            onClick={() => handleAction('START')}
          >
            Resume
          </Button>,
          <Button 
            key="cancel" 
            variant="contained" 
            color="error" 
            size="small"
            onClick={() => handleAction('CANCEL')}
          >
            Cancel
          </Button>
        ];

      default:
        return [
          <Button 
            key="cancel" 
            variant="contained" 
            color="error" 
            size="small"
            onClick={() => handleAction('CANCEL')}
          >
            Cancel
          </Button>
        ];
    }
    return [];
  };

  return (
    <Card 
      variant="outlined"
      sx={{
        borderLeft: `4px solid ${priorityColor}`,
        borderRadius: 2,
        marginBottom: compact ? 1 : 2,
        position: 'relative'
      }}
    >
      {order.priority === 'URGENT' && (
        <Box 
          position="absolute" 
          top={-4} 
          right={-4} 
          sx={{
            backgroundColor: '#ef4444',
            color: 'white',
            borderRadius: '50%',
            width: 20,
            height: 20,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: 10,
            animation: 'pulse 2s infinite'
          }}
        >
          !
        </Box>
      )}

      <CardHeader
        title={
          <Typography 
            variant="h6" 
            component="span"
            sx={{ flexGrow: 1 }}
          >
            {order.posOrderId}
          </Typography>
        }
        subheader={
          <Stack direction="row" spacing={1} alignItems="center">
            <Tooltip title={order.orderType}>
              <Badge 
                badgeContent={order.orderType} 
