## 5. Idempotency Repository (`src/repository/idempotencyRepo.ts`)

```typescript
import { createClient, RedisClientType } from 'redis';
import { config } from '../config';

/**
 * Simple wrapper around Redis SETNX with TTL.
 * Returns true if the eventId was NOT seen before (i.e., we can process).
 */
export class IdempotencyRepository {
  private client: RedisClientType;

  constructor() {
    this.client = createClient({
      socket: {
        host: config.redis.host,
        port: config.redis.port,
      },
      password: config.redis.password,
    });
    this.client.connect().catch(console.error);
  }

  /** Returns true if the eventId is new (we set it), false if duplicate. */
  async isNew(eventId: string): Promise<boolean> {
    const key = `${config.idempotencyKeyPrefix}${eventId}`;
    const setnx = await this.client.set(key, '1', {
      NX: true, // only set if not exists
      EX: config.redis.ttlSeconds,
    });
    return setnx === 'OK';
  }

  async close(): Promise<void> {
    await this.client.quit();
  }
}
```

