## 6. KDS Client with Retry (`src/client/kdsClient.ts`)

```typescript
import axios, { AxiosInstance, AxiosError } from 'axios';
import { config } from '../config';
import { KDSOrder } from '../types/kdsMessage';
import { retryMiddleware } from '../middleware/retryMiddleware';

/**
 * Thin wrapper around axios that applies the retry middleware.
 */
export class KdsClient {
  private http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      baseURL: config.kds.baseUrl,
      timeout: config.kds.timeoutMs,
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': config.kds.apiKey,
      },
    });
    // attach retry interceptor
    this.http.interceptors.request.use(
      async (config) => await retryMiddleware(config),
      (error) => Promise.reject(error)
    );
  }

  /** Sends a KDS order; throws on non‑2xx after retries. */
  async sendOrder(order: KDSOrder): Promise<void> {
    await this.http.post('/kds/orders', order);
  }
}
