## 7. Retry Middleware (`src/middleware/retryMiddleware.ts`)

```typescript
import { AxiosRequestConfig, AxiosError } from 'axios';
import { config } from '../config';

/**
 * Generic retry wrapper for axios requests.
 * Implements exponential back‑off with jitter.
 */
export async function retryMiddleware(
  config: AxiosRequestConfig
): Promise<any> {
  const { maxRetries = config.kds.maxRetries, backoffBaseMs = config.kds.backoffBaseMs } = config.kds;
  let attempt = 0;

  while (true) {
    try {
      // actual request is performed by axios after this interceptor resolves
      return await axios(config);
    } catch (err) {
      const axiosErr = err as AxiosError;
      // Do not retry on 4xx client errors (except 429)
      if (
        axiosErr.response?.status !== undefined &&
        axiosErr.response.status >= 400 &&
        axiosErr.response.status < 500 &&
        axiosErr.response.status !== 429
      ) {
        throw axiosErr;
      }

      attempt++;
      if (attempt > maxRetries) {
        throw axiosErr; // exhausted retries → will be handled by caller (DLQ)
      }

      const delay =
        backoffBaseMs * Math.pow(2, attempt - 1) + Math.random() * 100; // jitter
      await new Promise((res) => setTimeout(res, delay));
    }
  }
}
```

