## 8. Core Integration Service (`src/service/integrationService.ts`)

```typescript
import { IdempotencyRepository } from '../repository/idempotencyRepo';
import { KdsClient } from '../client/kdsClient';
import { PosEvent } from '../types/posEvent';
import { KDSOrder } from '../types/kdsMessage';
import { config } from '../config';
import { v4 as uuidv4 } from 'uuid';

/**
 * Transforms a POS event into a KDS order.
 * Only `create` and `modify` events produce a KDS message.
 * `pay` events are acknowledged but do not generate a KDS order
 * (they may be used for downstream analytics – omitted here).
 */
export class IntegrationService {
  private idempotency: IdempotencyRepository;
  private kdsClient: KdsClient;

  constructor() {
    this.idempotency = new IdempotencyRepository();
    this.kdsClient = new KdsClient();
  }

  /** Main entry point called by the webhook router. */
  async handlePosEvent(event: PosEvent): Promise<{ processed: boolean; reason?: string }> {
    // 1️⃣ Idempotency check
    const isNew = await this.idempotency.isNew(event.eventId);
    if (!isNew) {
      return { processed: false, reason: 'duplicate event' };
    }

    // 2️⃣ Only create/modify generate KDS orders
    if (event.type === 'create' || event.type === 'modify') {
      try {
        const kdsOrder = this.buildKdsOrder(event);
        await this.kdsClient.sendOrder(kdsOrder);
        return { processed: true };
      } catch (err) {
        // After retries are exhausted, forward to DLQ
        await this.sendToDlq(event, err as Error);
        return { processed: false, reason: 'sent to DLQ after retries' };
      }
    }

    // pay events: just acknowledge
    return { processed: true, reason: 'pay event acknowledged' };
  }

  /** Build a KDSOrder from a POS create/modify event. */
  private buildKdsOrder(event: PosEvent): KDSOrder {
    const base = event.type === 'create' ? event.order : {
      posOrderId: (event as PosModifyEvent).posOrderId,
      orderType: (event as PosModifyEvent).changes.orderType ?? 'DINE_IN',
      tableNumber: (event as PosModifyEvent).changes.tableNumber ?? null,
      items: (event as PosModifyEvent).changes.items ?? [],
      priority: (event as PosModifyEvent).changes.priority ?? 'NORMAL',
      specialInstructions: (event as PosModifyEvent).changes.specialInstructions ?? null,
    };

    // Ensure required fields are present – fallback defaults for missing modify fields
    const order: KDSOrder = {
      id: uuidv4(), // KDS‑side identifier (could also be posOrderId if you prefer)
      posOrderId: base.posOrderId,
      status: 'PENDING', // new orders always start pending
      priority: base.priority,
      orderType: base.orderType,
      tableNumber: base.tableNumber,
      items: base.items.map((it) => ({
        id: it.itemId,
        name: it.name,
        quantity: it.quantity,
        modifiers: it.modifiers ?? [],
        station: it.station,
        prepTimeSeconds: it.prepTimeSeconds,
        startedAt: undefined,
        completedAt: undefined,
      })),
      specialInstructions: base.specialInstructions,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    return order;
  }

  /** Send the original POS event to the DLQ endpoint (best‑effort). */
  private async sendToDlq(event: PosEvent, error: Error): Promise<void> {
    const payload = {
      originalEvent: event,
      failureReason: error.message,
      failedAt: new Date().toISOString(),
    };
    try {
      await fetch(config.dlq.endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
    } catch (dlqErr) {
      // If DLQ also fails we just log – the service should not crash.
      console.error('DLQ submission failed:', dlqErr);
    }
  }

  /** Graceful shutdown */
  async shutdown(): Promise<void> {
    await this.idempotency.close();
  }
}
