## 9. Express Routes (`src/routes/`)

### `src/routes/webhook.ts`

```typescript
import { Router } from 'express';
import { IntegrationService } from '../service/integrationService';
import { PosEvent } from '../types/posEvent';

export const webhookRouter = (service: IntegrationService) => {
  const router = Router();

  router.post('/', async (req, res) => {
    try {
      const event: PosEvent = req.body;
      // Basic shape validation (could be replaced with Joi/Zod)
      if (!event || !event.eventId || !event.type) {
        return res.status(400).json({ error: 'invalid POS event' });
      }

      const result = await service.handlePosEvent(event);
      if (!result.processed) {
        // 202 Accepted – we have either deduplicated or sent to DLQ
        return res.status(202).json({ status: 'accepted', reason: result.reason });
      }
      return res.status(200).json({ status: 'processed' });
    } catch (err) {
      console.error('Webhook error:', err);
      return res.status(500).json({ error: 'internal server error' });
    }
  });

  return router;
};
```

