## 10. Application Bootstrap (`src/index.ts`)

```typescript
import express from 'express';
import { webhookRouter } from './routes/webhook';
import { dlqRouter } from './routes/dlq';
import { healthRouter } from './routes/health';
import { IntegrationService } from './service/integrationService';
import { config } from './config';

async function start() {
  const app = express();
  app.use(express.json());

  const integrationService = new IntegrationService();

  // Routes
  app.use('/pos/webhook', webhookRouter(integrationService));
  app.use('/dlq', dlqRouter());
  app.use('/health', healthRouter());

  const port = config.port;
  app.listen(port, () => {
    console.log(`🚀 POS‑KDS Integration Service listening on http://localhost:${port}`);
  });

  // Graceful shutdown
  const shutdown = async () => {
    console.log('🛑 Shutting down...');
    await integrationService.shutdown();
    process.exit(0);
  };
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}

start().catch((err) => {
  console.error('❌ Failed to start service:', err);
  process.exit(1);
});
