  } = useOrdersWebSocket();

  const [stationFilter, setStationFilter] = useState<string[]>(['GRILL', 'FRYER', 'SALAD', 'DESSERT', 'BAR']);

  // Filter orders by station
  const filteredOrders = useMemo(() => {
    if (stationFilter.length === 0) return [];
    return ordersList.filter(order => 
      order.items.some(item => stationFilter.includes(item.station))
    );
  }, [ordersList, stationFilter]);

  // Group orders by status for Kanban view
  const groupedOrders = useMemo(() => {
    const groups: Record<KDSOrder['status'], KDSOrder[]> = {
      PENDING: [],
      PREPARING: [],
      READY: [],
      HELD: [],
      CANCELLED: [],
      COMPLETED: []
    };

    filteredOrders.forEach(order => {
      groups[order.status].push(order);
    });

    return groups;
  }, [filteredOrders]);

  const handleAction = async (action: KDSCommandPayload['action'], itemIds?: string[]) => {
    // In a real implementation, we would get the user ID from auth
    const userId = 'kitchen-staff-001'; // Placeholder

    // For simplicity, we're sending the command for the first order in the list
    // In reality, this would be called from OrderCard with specific order ID
    if (filteredOrders.length > 0) {
      const orderId = filteredOrders[0].id;
      await sendCommand({
        orderId,
        action,
        itemIds: itemIds || undefined,
        userId,
        timestamp: new Date().toISOString()
      });
    }
  };

  const handleStationFilterChange = (stations: string[]) => {
    setStationFilter(stations);
  };

  // Order counts by status
  const orderCounts = useMemo(() => {
    const counts: Record<KDSOrder['status'], number> = {
      PENDING: 0,
      PREPARING: 0,
      READY: 0,
      HELD: 0,
      CANCELLED: 0,
      COMPLETED: 0
    };

    orders.forEach((order) => {
      counts[order.status] = (counts[order.status] || 0) + 1;
    });

    return counts;
  }, [orders]);

  if (connectionStatus === 'ERROR') {
    return (
      <Alert severity="error" sx={{ p: 2, m: 2 }}>
        Connection error: Unable to connect to kitchen display service. Please check your network and try again.
      </Alert>
    );
  }

  if (connectionStatus === 'CONNECTING') {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '80vh' }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Connecting to kitchen display service...</Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 2 }}>
      <KDSHeader 
        stationFilter={stationFilter}
        onStationFilterChange={handleStationFilterChange}
        connectionStatus={connectionStatus}
        orderCounts={orderCounts}
      />

      <Box sx={{ mt: 2, display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 2 }}>
        {Object.keys(groupedOrders).map((status) => (
