            <Typography variant="h6" sx={{ mb: 2 }}>
              {status} Orders ({groupedOrders[status as KDSOrder['status']].length})
            </Typography>

            {groupedOrders[status as KDSOrder['status']].length === 0 ? (
              <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', pt: 2 }}>
                No orders in this status
              </Typography>
            ) : (
              <>
                {groupedOrders[status as KDSOrder['status']].map((order) => (
                  <OrderCard 
                    key={order.id} 
                    order={order} 
                    onAction={handleAction}
                    compact={window.innerWidth < 600}
                  />
                ))}
              </>
            )}
          </Box>
        ))}
      </Box>
    </Box>
  );
