import { Config } from '../config';

/**
 * Simple in‑memory idempotency store.
 * In production replace with Redis SET NX EX or a DB unique constraint.
 */
export class IdempotencyStore {
  private readonly seen = new Set<string>();
  private readonly ttlMs: number;

  constructor(ttlMs: number = config.idempotencyTtlMs) {
    this.ttlMs = ttlMs;
    // Optional: clean‑up timer to avoid unbounded growth.
    setInterval(() => this.clearExpired(), this.ttlMs);
  }

  /** Returns true if the id was already processed. */
  async exists(id: string): Promise<boolean> {
    return this.seen.has(id);
  }

  /** Marks an id as processed. */
  async mark(id: string): Promise<void> {
    this.seen.add(id);
  }

  /** No‑op expiration for the in‑memory version – kept for interface compatibility. */
  private clearExpired(): void {
    // In a real Redis store we would rely on TTL; here we do nothing.
  }
}
