import axios, { AxiosInstance, AxiosError } from 'axios';
import { Config } from '../config';
import { KdsOrderMessage } from '../types/kds';
import { logger } from '../utils/logger';

/**
 * Thin wrapper around Axios that posts a KDS order message.
 * Retries are handled by the retry middleware (see below).
 */
export class KdsClient {
  private readonly http: AxiosInstance;

  constructor(baseURL: string = config.kdsEndpoint) {
    this.http = axios.create({
      baseURL,
      timeout: 5000,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  /** Sends a KDS order message. Throws on non‑2xx response. */
  async send(message: KdsOrderMessage): Promise<void> {
    try {
      await this.http.post('', message);
      logger.info(`KDS message sent for posOrderId=${message.posOrderId}`);
    } catch (err) {
      const axiosErr = err as AxiosError;
      logger.error(
        `Failed to send KDS message for posOrderId=${message.posOrderId}:`,
        axiosErr.response?.data ?? axiosErr.message
      );
      throw err;
    }
  }
}
