import { KdsOrderMessage } from '../types/kds';
import { logger } from '../utils/logger';

/**
 * Dead‑Letter Queue – in‑memory array for demo.
 * Replace with BullMQ, RabbitMQ, or SQS in production.
 */
export class DeadLetterQueue {
  private readonly queue: KdsOrderMessage[] = [];

  /** Push a failed message onto the DLQ. */
  async enqueue(message: KdsOrderMessage): Promise<void> {
    this.queue.push(message);
    logger.warn(`Message enqueued to DLQ (posOrderId=${message.posOrderId}). Queue length: ${this.queue.length}`);
  }

  /** Retrieve all messages (for testing / manual replay). */
  async drain(): Promise<KdsOrderMessage[]> {
    const copy = [...this.queue];
    this.queue.length = 0;
    return copy;
  }

  /** Current length – useful for health checks. */
  size(): number {
    return this.queue.length;
  }
}
