## 5. Middleware  

### `src/middleware/retryMiddleware.ts`
```typescript
import axios, { AxiosInstance, AxiosError, InternalAxiosRequestConfig } from 'axios';
import { Config } from '../config';
import { logger } from '../utils/logger';

/**
 * Attach a retry interceptor to an Axios instance.
 * Implements exponential back‑off with jitter.
 */
export function attachRetryInterceptor(http: AxiosInstance): void {
  http.interceptors.response.use(
    (response) => response, // pass through successful responses
    async (error: AxiosError) => {
      const { config, code } = error;
      // Do not retry on 4xx client errors (except 429) or network errors that are not idempotent.
      if (config?.method?.toLowerCase() === 'get' && code === 'ECONNABORTED') {
        // timeout – retry
      } else if (code && code.startsWith('4')) {
        // 4xx – do not retry unless 429 (rate limit)
        if (code !== '429') return Promise.reject(error);
      }

      // Determine retry count from custom header or fallback to 0.
      const retryCount = config?.['retryCount'] ?? 0;
      if (retryCount >= config.maxRetries) {
        logger.warn(`Max retries (${config.maxRetries}) exceeded for ${config?.url}`);
        return Promise.reject(error);
      }

      // Exponential back‑off with jitter.
      const delay =
        config.retryBaseDelayMs * Math.pow(2, retryCount) +
        Math.floor(Math.random() * 100);
      logger.info(
        `Retry attempt ${retryCount + 1}/${config.maxRetries} after ${delay}ms for ${config?.url}`
      );

      // Wait then retry.
      return new Promise((resolve) => {
        setTimeout(async () => {
          // Clone config and increment retry counter.
          const retryConfig = { ...config, ['retryCount']: retryCount + 1 };
          try {
            const resp = await http.request(retryConfig);
            resolve(resp);
          } catch (err) {
            resolve(Promise.reject(err));
          }
        }, delay);
      });
    }
  );
}

/**
 * Factory that returns an Axios instance with retry interceptor attached.
 */
export function createHttpClient(baseURL: string): AxiosInstance {
  const http = axios.create({ baseURL, timeout: 5000 });
  attachRetryInterceptor(http);
  return http;
}
