## 6. Controller  

### `src/controllers/posWebhookController.ts`
```typescript
import { Request, Response, NextFunction } from 'express';
import { PosOrderEvent, PosEventType } from '../types/pos';
import { KdsOrderMessage, KdsOrderStatus, KdsOrderPriority } from '../types/kds';
import { IdempotencyStore } from '../services/idempotencyStore';
import { KdsClient } from '../services/kdsClient';
import { DeadLetterQueue } from '../services/dlq';
import { logger } from '../utils/logger';
import { Config } from '../config';

export class PosWebhookController {
  constructor(
    private readonly idempotencyStore: IdempotencyStore,
    private readonly kdsClient: KdsClient,
    private readonly dlq: DeadLetterQueue
  ) {}

  /** Express route handler. */
  async handler(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const event: PosOrderEvent = req.body;

      // Basic validation – in production use Joi/Zod.
      if (!event.eventId || !PosEventType[event.eventType] || !event.posOrderId) {
        res.status(400).json({ error: 'Invalid POS event payload' });
        return;
      }

      // Idempotency check.
      if (await this.idempotencyStore.exists(event.eventId)) {
        logger.info(`Duplicate event ignored: ${event.eventId}`);
        res.status(202).json({ message: 'Event already processed' });
        return;
      }

      // Transform POS event → KDS message.
      const kdsMsg = this.transform(event);

      // Send to KDS (retries handled inside KdsClient via axios interceptor).
      try {
        await this.kdsClient.send(kdsMsg);
        // Mark as processed only after successful delivery.
        await this.idempotencyStore.mark(event.eventId);
        res.status(202).json({ message: 'Event accepted and forwarded' });
      } catch (sendErr) {
        // If sending fails after retries, push to DLQ.
        await this.dlq.enqueue(kdsMsg);
        // Still mark as processed to avoid infinite retry loops on the same event.
        await this.idempotencyStore.mark(event.eventId);
        logger.error(`Event ${event.eventId} failed after retries – moved to DLQ`);
        // Respond with 502 so the POS can optionally retry later.
        res.status(502).json({ error: 'Failed to forward to KDS – see DLQ' });
      }
    } catch (err) {
      next(err);
    }
  }

  /** Mapping logic – keep it pure for easy unit testing. */
  private transform(event: PosOrderEvent): KdsOrderMessage {
    const statusMap: Record<PosEventType, KdsOrderStatus> = {
      [PosEventType.ORDER_CREATED]: KdsOrderStatus.PENDING,
      [PosEventType.ORDER_MODIFIED]: KdsOrderStatus.PENDING, // treat as refresh
      [PosEventType.ORDER_PAID]: KdsOrderStatus.PENDING, // KDS will move to PREPARING later
    };

    const priorityMap: Record<string, KdsOrderPriority> = {
      HIGH: KdsOrderPriority.HIGH,
      URGENT: KdsOrderPriority.URGENT,
    };

    // Derive priority from optional POS field (if present) – default NORMAL.
    const priority =
      (event.data as any).priority && priorityMap[(event.data as any).priority]
        ? (event.data as any).priority
        : KdsOrderPriority.NORMAL;

    const items: KdsOrderItem[] = event.data.items.map((it) => ({
      id: it.itemId,
      name: it.name,
      quantity: it.quantity,
      modifiers: it.modifiers,
      station: it.station,
      prepTimeSeconds: it.prepTimeSeconds,
    }));

    return {
      integrationId: event.eventId, // reuse POS event id for idempotency
      posOrderId: event.posOrderId,
      status: statusMap[event.eventType],
      priority,
      items,
      posEventTimestamp: event.timestamp,
      createdAt: new Date().toISOString(),
    };
  }
}
