### `src/app.ts`
```typescript
import express, { Request, Response, NextFunction } from 'express';
import { PosWebhookController } from './controllers/posWebhookController';
import { IdempotencyStore } from './services/idempotencyStore';
import { KdsClient } from './services/kdsClient';
import { DeadLetterQueue } from './services/dlq';
import { errorHandler } from './middleware/errorHandler';
import { logger } from './utils/logger';

export function buildApp(): express.Express {
  const app = express();

  // Body parsing – assume JSON payloads.
  app.use(express.json());

  // Dependency injection (simple manual DI for clarity).
  const idempotencyStore = new IdempotencyStore();
  const kdsClient = new KdsClient();
  const dlq = new DeadLetterQueue();
  const controller = new PosWebhookController(idempotencyStore, kdsClient, dlq);

  // POS webhook endpoint.
  app.post('/pos/webhook', controller.handler.bind(controller));

  // Health check.
  app.get('/health', (_req: Request, res: Response) => {
    res.json({ status: 'OK', timestamp: new Date().toISOString() });
  });

  // DLQ inspection (dev only).
  if (process.env.NODE_ENV !== 'production') {
    app.get('/dlq', async (_req: Request, res: Response) => {
      const messages = await dlq.drain();
      res.json({ count: messages.length, messages });
    });
  }

  // 404 handler.
  app.use((_req: Request, _res: Response, next: NextFunction) => {
    next({ status: 404, message: 'Not Found' });
  });

  // Central error handler.
  app.use(errorHandler);

  return app;
}
```

