// src/services/transformer.ts
import { PosOrderEvent, KdsOrderMessage, OrderType, OrderStatus } from '../types/contracts';
import { v4 as uuidv4 } from 'uuid';

/**
 * Transforms a POS order event into a KDS order message.
 * @param posEvent The POS order event
 * @returns KDS order message
 */
export function buildKdsMessage(posEvent: PosOrderEvent): KdsOrderMessage {
  const messageId = uuidv4();

  const kdsItems = posEvent.items.map((posItem, index) => {
    // Determine station and prep time based on item name
    let station: 'GRILL' | 'FRY' | 'SALAD' | 'EXPO' | 'BAR' = 'EXPO';
    let prepTimeSeconds = 0;

    const itemName = posItem.name.toLowerCase();
    if (itemName.includes('burger') || itemName.includes('steak') || itemName.includes('chicken')) {
      station = 'GRILL';
      prepTimeSeconds = 180;
    } else if (itemName.includes('fry') || itemName.includes('fries') || itemName.includes('onion ring')) {
      station = 'FRY';
      prepTimeSeconds = 180;
    } else if (itemName.includes('salad') || itemName.includes('vegetable')) {
      station = 'SALAD';
      prepTimeSeconds = 60;
    } else if (itemName.includes('dessert') || itemName.includes('cake') || itemName.includes('ice cream')) {
      station = 'DESSERT';
      prepTimeSeconds = 120;
    } else if (itemName.includes('drink') || itemName.includes('beer') || itemName.includes('wine') || itemName.includes('soda')) {
      station = 'BAR';
      prepTimeSeconds = 30;
    }

    const modifierNames = posItem.modifiers.map(mod => mod.name);

    return {
      kdsItemId: `${posItem.posItemId}-${index}`,
      name: posItem.name,
      quantity: posItem.quantity,
      modifiers: modifierNames,
      prepTimeSeconds,
      station,
    };
  });

  // Determine priority based on order type and status
  let priority: number = 3; // default medium
  if (posEvent.orderType === 'DELIVERY' || posEvent.orderType === 'TAKEOUT') {
    priority = 2; // higher priority for delivery/takeout
  } else if (posEvent.status === 'PAID') {
    priority = 1; // highest priority for paid orders
  }

  return {
    messageId,
    correlationId: posEvent.eventId,
    posOrderId: posEvent.posOrderId,
    posLocationId: posEvent.posLocationId,
    orderType: posEvent.orderType,
    status: posEvent.status,
    items: kdsItems,
    firedAt: new Date().toISOString(),
    priority,
    sourceEventType: posEvent.eventType,
  };
}
