import axios, { AxiosInstance } from 'axios';
import { config } from '../config';
import { attachKdsMetadataInterceptor, attachRetryInterceptor } from '../middleware/retryMiddleware';
import { KdsOrderMessage } from '../types/contracts';
import pino from 'pino';
import { v4 as uuidv4 } from 'uuid';

const logger = pino({ name: 'kds-client' });

/**
 * Creates and configures an Axios instance for communicating with the KDS.
 * @param dlqHandler A function to handle sending failed messages to the dead-letter queue.
 * @returns Configured Axios instance.
 */
export function createKdsClient(
  dlqHandler: (entry: Omit<DeadLetterEntry, 'id' | 'createdAt'>) => Promise<void>
): AxiosInstance {
  const instance = axios.create({
    baseURL: config.kds.baseUrl,
    timeout: config.kds.timeoutMs,
    headers: {
      'Content-Type': 'application/json',
      'X-API-KEY': config.kds.apiKey,
    },
  });

  // Attach interceptors: request interceptor first, then response interceptor for retries
  attachKdsMetadataInterceptor(instance);
  attachRetryInterceptor(instance, dlqHandler);

  return instance;
}

/**
 * Sends a KDS order message to the KDS system.
 * @param kdsMessage The KDS message to send.
 * @param dlqHandler A function to handle sending failed messages to the dead-letter queue.
 * @returns Promise that resolves when the message is successfully sent.
 */
export async function sendToKds(
  kdsMessage: KdsOrderMessage,
  dlqHandler: (entry: Omit<DeadLetterEntry, 'id' | 'createdAt'>) => Promise<void>
): Promise<void> {
  const kdsClient = createKdsClient(dlqHandler);

  try {
    await kdsClient.post('/api/v1/orders', kdsMessage);
    logger.info({ 
      messageId: kdsMessage.messageId, 
      posOrderId: kdsMessage.posOrderId 
    }, 'KDS message sent successfully');
  } catch (error) {
    logger.error({ 
      messageId: kdsMessage.messageId, 
      posOrderId: kdsMessage.posOrderId, 
      error: error.message 
    }, 'Failed to send KDS message');
    throw error;
  }
}
