export type OrderStatus =
  | 'PENDING'
  | 'PREPARING'
  | 'READY'
  | 'HELD'
  | 'CANCELLED'
  | 'COMPLETED';

export interface POSOrder {
  id: string; // UUID generated by POS
  posOrderId: string; // Human‑readable (e.g., "ORD-1024")
  items: {
    id: string;
    name: string;
    quantity: number;
    modifiers: string[];
    station: 'GRILL' | 'FRYER' | 'SALAD' | 'DESSERT' | 'BAR';
    prepTimeSeconds: number;
  }[];
  createdAt: string; // ISO timestamp
}

export interface KDSOrder extends POSOrder {
  status: OrderStatus;
  updatedAt: string; // ISO timestamp when KDS last touched it
