### 2.3. Unit / Integration Test – Order Propagation Latency  
**File:** `backend/__tests__/orderPropagation.test.ts`

```ts
import axios from 'axios';
import { POSOrder, KDSOrder } from '../src/types/kds';
import { v4 as uuidv4 } from 'uuid';
import { startServer, stopServer } from '../src/server'; // helper that boots Express in‑memory

const BASE_URL = 'http://localhost:3000/api';

describe('POS → KDS order propagation latency', () => {
  let server: any;

  beforeAll(async () => {
    server = await startServer(); // spins up the app on a random port, returns {app, port}
  });

  afterAll(async () => {
    await stopServer(server);
  });

  test('single order propagates with ≤150 ms average latency (over 30 runs)', async () => {
    const latencies: number[] = [];

    for (let i = 0; i < 30; i++) {
      const order: POSOrder = {
        id: uuidv4(),
        posOrderId: `ORD-${Date.now()}-${i}`,
        items: [
          {
            id: uuidv4(),
            name: 'Cheeseburger',
            quantity: 1,
            modifiers: ['No Pickles'],
            station: 'GRILL',
            prepTimeSeconds: 120,
          },
        ],
        createdAt: new Date().toISOString(),
      };

      const t0 = performance.now();
      // 1️⃣ POS posts order to integration layer
      await axios.post(`${BASE_URL}/orders`, order);
      // 2️⃣ Poll KDS endpoint until order appears (max 2 s)
      let kdsOrder: KDSOrder | null = null;
      const deadline = Date.now() + 2000;
      while (Date.now() < deadline && !kdsOrder) {
        const resp = await axios.get(`${BASE_URL}/kds/orders/${order.posOrderId}`);
        kdsOrder = resp.data as KDSOrder;
        await new Promise((r) => setTimeout(r, 20)); // 20 ms poll interval
      }
      const t1 = performance.now();

      expect(kdsOrder).not.toBeNull();
      expect(kdsOrder?.status).toBe('PENDING'); // initial KDS status
      latencies.push(t1 - t0);
    }

    const avgLatency =
      latencies.reduce((sum, v) => sum + v, 0) / latencies.length;
    console.log(`Average propagation latency: ${avgLatency.toFixed(2)} ms`);
    expect(avgLatency).toBeLessThanOrEqual(150); // acceptance criteria
  });
});
```

### 2.4. Unit / Integration Test – Error Handling Under Load  
**File:** `backend/__tests__/errorHandling.test.ts`

```ts
import axios from 'axios';
import { startServer, stopServer } from '../src/server';
import { v4 as uuidv4 } from 'uuid';

const BASE_URL = 'http://localhost:3000/api';

describe('Error handling & retry under load', () => {
  let server: any;

  beforeAll(async () => {
    server = await startServer();
  });

  afterAll(async () => {
    await stopServer(server);
  });

  test('5xx responses trigger retry and eventual success', async () => {
    // Simulate a flaky backend: first 2 calls return 503, third succeeds
    // (Assume the integration layer has retryMiddleware configured)
    const order = {
      id: uuidv4(),
      posOrderId: `ORD-RETRY-${Date.now()}`,
      items: [
        {
          id: uuidv4(),
          name: 'Fries',
          quantity: 1,
          modifiers: [],
          station: 'FRYER',
          prepTimeSeconds: 90,
        },
      ],
      createdAt: new Date().toISOString(),
    };

    const responses: number[] = [];
    for (let attempt = 0; attempt < 5; attempt++) {
      try {
        await axios.post(`${BASE_URL}/orders`, order);
        responses.push(200);
        break; // success – exit loop
      } catch (err: any) {
        if (err.response?.status >= 500) {
          responses.push(err.response.status);
          await new Promise((r) => setTimeout(r, 100)); // back‑off
          continue;
        }
        throw err; // non‑retryable error
      }
    }

    expect(responses).toContain(200);
    expect(responses.filter((s) => s === 503).length).toBeGreaterThanOrEqual(2);
  });
});
```

> **Why Jest?**  
> * Fast, zero‑config for TS via `ts-jest`.  
> * Built‑in mocking (`jest.mock`) lets us stub external services (e.g., payment gateway) without touching real infrastructure.  

