### 3.4. Error‑Handling UI Test (`cypress/e2e/errorHandling.cy.ts`)

```ts
/// <reference types="cypress" />

describe('KDS UI – error handling under load', () => {
  it('shows retry toast when backend returns 5xx and recovers', () => {
    // Intercept POST to /api/orders and fail first 2 times
    cy.intercept('POST', '/api/orders', (req) => {
      if (req.headers['x-retry-count'] === undefined) {
        req.headers['x-retry-count'] = '0';
      }
      const count = Number(req.headers['x-retry-count']);
      if (count < 2) {
        req.headers['x-retry-count'] = String(count + 1);
        req.reply({ statusCode: 503, body: { error: 'Service Unavailable' } });
      } else {
        req.reply({ statusCode: 200, body: { success: true } });
      }
    }).as('flakyPost');

    const order = {
      id: '11111111-1111-1111-1111-111111111111',
      posOrderId: `ORD-ERR-${Date.now()}`,
      items: [
        {
          id: '22222222-2222-2222-2222-222222222222',
          name: 'Burger',
          quantity: 1,
          modifiers: [],
          station: 'GRILL',
          prepTimeSeconds: 120,
        },
      ],
      createdAt: new Date().toISOString(),
    };

    cy.visit('/');
    cy.postPOSOrder(order); // uses custom command that sends x-retry-count header via request interceptor

    // Expect a toast notification about retry
    cy.get('.toast-retry')
      .should('be.visible')
      .and('contain', 'Retrying…');

    // After the third attempt succeeds, order should appear
    cy.waitForKdsOrder(order.posOrderId);
    cy.get('.toast-retry').should('not.exist'); // toast cleared on success
  });
});
```

> **Cypress Tips**  
> * `cy.intercept` lets us simulate flaky backend behavior without touching real services.  
> * Custom command `postPOSOrder` re‑uses the same request shape the integration layer expects, keeping UI tests in sync with contract tests.  

