## 4. Performance Testing (k6)

### 4.1. k6 Options (`k6/k6.options.js`)

```js
export const options = {
  thresholds: {
    // 95th percentile of order propagation latency must be ≤150 ms
    'http_req_duration{endpoint:/api/orders}': ['p(95)<150'],
    // Overall request success rate
    checks: ['rate>0.99'],
  },
  // Simulate a realistic POS peak: 50 VUs ramping up to 200 VUs over 2 min
  stages: [
    { duration: '30s', target: 50 },
    { duration: '60s', target: 150 },
    { duration: '30s', target: 200 },
    { duration: '30s', target: 0 },
  ],
};
```

### 4.2. Load Script – POS → KDS Latency (`k6/posKdsLoad.test.js`)

```js
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Trend } from 'k6/metrics';

// Custom metric: order propagation latency (POS POST → KDS GET)
const propagationLatency = new Trend('order_propagation_latency');

export default function () {
  // ---------- 1️⃣ POS creates order ----------
  const posPayload = {
    id: __VU.toString() + '-' + Date.now(),
    posOrderId: `ORD-Load-${__VU}-${Date.now()}`,
    items: [
      {
        id: 'item-1',
        name: 'Load Test Item',
        quantity: 1,
        modifiers: [],
        station: 'GRILL',
        prepTimeSeconds: 30,
      },
    ],
    createdAt: new Date().toISOString(),
  };

  const posRes = http.post('http://backend:3000/api/orders', JSON.stringify(posPayload), {
    headers: { 'Content-Type': 'application/json' },
    timeout: '10s',
  });

  check(posRes, {
    'POS order created': (r) => r.status === 201,
  });

  // ---------- 2️⃣ Poll KDS until order appears (max 2 s) ----------
  const start = Date.now();
  let kdsOrder = null;
  while (Date.now() - start < 2000 && !kdsOrder) {
    const kdsRes = http.get(
      `http://backend:3000/api/kds/orders/${posPayload.posOrderId}`,
      { timeout: '2s' }
    );
    if (kdsRes.status === 200) {
      kdsOrder = kdsRes.json();
    }
    sleep(0.02); // 20 ms poll interval
  }

  const end = Date.now();
  const latency = end - start; // ms

  // Record latency for threshold evaluation
  propagationLatency.add(latency);

  // Optional: assert that order made it to KDS
  check(kdsOrder, {
    'order appeared in KDS': (o) => o !== null,
    'order status is PENDING': (o) => o && o.status === 'PENDING',
  });

  // Think time between simulated POS clients
  sleep(0.5);
}
```

**Explanation**

* The script mimics many concurrent POS terminals (VUs).  
* Each iteration posts an order, then polls the KDS endpoint until the order appears or a 2‑second timeout hits.  
* The measured latency (`propagationLatency`) is fed into a k6 **Threshold** (`p(95)<150`). If the 95th‑percentile exceeds 150 ms, the k6 run fails – satisfying the acceptance criterion.  

### 4.3. Running k6 locally (for dev)

```bash
