### 3.4 `backend/src/services/kdsClient.ts`

```typescript
import axios, { AxiosInstance } from 'axios';
import { KdsOrderDto } from '../types/contracts';
import { logger } from '../utils/logger';

export class KdsClient {
  private readonly http: AxiosInstance;

  constructor(baseURL: string, timeout = 5000) {
    this.http = axios.create({
      baseURL,
      timeout,
      headers: { 'Content-Type': 'application/json' }
    });

    // Simple retry on network errors or 5xx
    this.http.interceptors.response.use(
      (res) => res,
      async (err) => {
        const { config, response } = err;
        if (!config || !response) return Promise.reject(err);
        // Retry idempotent GET/POST on 5xx or network error
        const shouldRetry =
          (response.status >= 500 && response.status < 600) ||
          !response;
        if (shouldRetry) {
          logger.warn(`Retrying KDS request to ${config.url} after ${response?.status ?? 'network error'}`);
          return this.http(config);
        }
        return Promise.reject(err);
      }
    );
  }

  async submitOrder(order: PosOrderDto): Promise<KdsOrderDto> {
    const resp = await this.http.post<KdsOrderDto>('/orders', order);
    logger.info(`KDS order created: ${resp.data.id}`);
    return resp.data;
  }

  async getOrder(orderId: string): Promise<KdsOrderDto> {
    const resp = await this.http.get<KdsOrderDto>(`/orders/${orderId}`);
    return resp.data;
  }
}
```

### 3.5 `backend/src/services/orderService.ts`

```typescript
import { KdsClient } from './kdsClient';
import { PosOrderDto, KdsOrderDto } from '../types/contracts';
import { logger } from '../utils/logger';
import { IdempotencyStore } from './idempotencyStore';

export class OrderService {
  private readonly kds: KdsClient;
  private readonly idempotency: IdempotencyStore;

  constructor(kdsBaseUrl: string, redisUrl: string) {
    this.kds = new KdsClient(kdsBaseUrl);
    this.idempotency = new IdempotencyStore(redisUrl);
  }

  /**
   * Called by POS‑adapter webhook.
   * Guarantees at‑most‑once processing via Redis‑based idempotency key.
   */
  async handlePosOrder(posOrder: PosOrderDto): Promise<KdsOrderDto> {
    const idempotencyKey = `pos:${posOrder.posOrderId}`;
    const cached = await this.idempotency.get<KdsOrderDto>(idempotencyKey);
    if (cached) {
      logger.info(`Returning cached KDS order for ${posOrder.posOrderId}`);
      return cached;
    }

    const kdsOrder = await this.kds.submitOrder(posOrder);
    await this.idempotency.set(idempotencyKey, kdsOrder, { ttl: 3600 }); // 1 h
    logger.info(`Persisted new KDS order ${kdsOrder.id} for POS ${posOrder.posOrderId}`);
    return kdsOrder;
  }
}
```

### 3.6 `backend/src/services/idempotencyStore.ts`

```typescript
import Redis from 'ioredis';

export class IdempotencyStore {
  private readonly client: Redis;

  constructor(redisUrl: string) {
    this.client = new Redis(redisUrl);
  }

  async get<T>(key: string): Promise<T | null> {
    const raw = await this.client.get(key);
    return raw ? (JSON.parse(raw) as T) : null;
  }

  async set<T>(key: string, value: T, opts: { ttl?: number } = {}): Promise<void> {
    const payload = JSON.stringify(value);
    if (opts.ttl) {
      await this.client.set(key, payload, 'EX', opts.ttl);
    } else {
      await this.client.set(key, payload);
    }
  }

  async del(key: string): Promise<void> {
    await this.client.del(key);
  }
}
