import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter, Trend } from 'k6/metrics';

// Custom metrics
export const latencyTrend = new Trend('order_propagation_latency');
export const errorCounter = new Counter('order_propagation_errors');

// Configuration – can be overridden via ENV
export const options = {
  stages: [
    { duration: '2m', target: 20 },   // ramp‑up to 20 VUs
    { duration: '5m', target: 20 },   // steady state
    { duration: '2m', target: 0 }     // ramp‑down
  ],
  thresholds: {
    // Defined also in k6.config.js but duplicated here for IDE hints
    'order_propagation_latency': ['avg<150', 'p(95)<200'],
    'order_propagation_errors': ['rate<0.01']
  }
};

const POS_API = __ENV.POS_API_URL || 'http://host.docker.internal:8080/pos/webhook';

export default function () {
  const payload = {
    posOrderId: `LOAD-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
    items: [
      {
        name: 'Load Burger',
        quantity: 1 + Math.floor(Math.random() * 3),
        station: 'GRILL',
        modifiers: [],
        prepTimeSeconds: 60 + Math.floor(Math.random() * 120)
      },
      {
        name: 'Load Fries',
        quantity: 1 + Math.floor(Math.random() * 2),
        station: 'FRYER',
        modifiers: ['No Salt'],
        prepTimeSeconds: 40 + Math.floor(Math.random() * 80)
      }
    ]
  };

  const params = {
    timeout: '10s',
    headers: { 'Content-Type': 'application/json' }
  };

  let res;
  try {
    res = http.post(POS_API, JSON.stringify(payload), params);
  } catch (err) {
    errorCounter.add(1);
    console.error(`Request failed: ${err}`);
    return;
  }

  const ok = check(res, {
    'status is 202': (r) => r.status === 202,
    'has accepted flag': (r) => r.json().accepted === true
  });

  if (!ok) {
    errorCounter.add(1);
  }

  // Record latency (time to get 202 from POS‑adapter)
  latencyTrend.add(res.timings.duration);

  // Think time between orders – simulates realistic kitchen pace
  sleep(1 + Math.random() * 2);
}
