import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter } from 'k6/metrics';

export const errorInjectCounter = new Counter('fault_injection_errors');

export const options = {
  stages: [
    { duration: '1m', target: 10 },
    { duration: '3m', target: 10 },
    { duration: '1m', target: 0 }
  ],
  thresholds: {
    'fault_injection_errors': ['rate<0.05'] // allow up to 5% injected errors
  }
};

const POS_API = __ENV.POS_API_URL || 'http://host.docker.internal:8080/pos/webhook';
const FAULT_PROBABILITY = 0.1; // 10% of requests will be malformed

export default function () {
  let payload;
  if (Math.random() < FAULT_PROBABILITY) {
    // Intentionally bad payload – missing required field
    payload = { posOrderId: `FAULT-${Date.now()}` };
  } else {
    payload = {
      posOrderId: `OK-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
      items: [
        {
          name: 'Fault Burger',
          quantity: 1,
          station: 'GRILL',
          modifiers: [],
          prepTimeSeconds: 100
        }
      ]
    };
  }

  const res = http.post(POS_API, JSON.stringify(payload), {
    headers: { 'Content-Type': 'application/json' },
    timeout: '5s'
  });

  const ok = check(res, {
    'responds (2xx or 400)': (r) => r.status === 202 || r.status === 400,
    'error payload contains error field when 400': (r) =>
      r.status === 400 && !!r.json().error
  });

  if (!ok) {
    errorInjectCounter.add(1);
  }

  sleep(0.5 + Math.random() * 1.5);
}
