#### 2.1 `src/services/retryMiddleware.ts`

```ts
// src/services/retryMiddleware.ts
import axios, { AxiosInstance, AxiosError, InternalAxiosRequestConfig } from 'axios';

/**
 * Returns an axios instance with exponential‑backoff retry logic.
 * Retries on network errors or 5xx responses.
 */
export function createRetryAxiosInstance(
  baseURL: string,
  maxRetries = 3,
  baseDelayMs = 100
): AxiosInstance {
  const instance = axios.create({ baseURL, timeout: 5000 });

  // Request interceptor – we could add headers here if needed
  instance.interceptors.request.use(
    (config: InternalAxiosRequestConfig) => config,
    (error) => Promise.reject(error)
  );

  // Response interceptor – handles retries
  instance.interceptors.response.use(
    (response) => response,
    async (error: AxiosError) => {
      const { config, response, code } = error;

      // Do not retry if maxRetries reached or if it's a client error (4xx) that is not 429
      if (!config || config.__retryCount >= maxRetries) {
        return Promise.reject(error);
      }

      const shouldRetry =
        // Network error (no response) OR
        !response ||
        // 5xx server errors OR
        (response.status >= 500 && response.status < 600) ||
        // Rate‑limit (429) – treat as retryable
        response.status === 429;

      if (!shouldRetry) {
        return Promise.reject(error);
      }

      // Increment retry counter
      config.__retryCount = (config.__retryCount || 0) + 1;

      // Exponential backoff with jitter
      const delay = baseDelayMs * 2 ** (config.__retryCount - 1) + Math.random() * 10;
      await new Promise((res) => setTimeout(res, delay));

      return instance(config);
    }
  );

  return instance;
}
```

#### 2.2 `src/services/transformer.ts`

```ts
// src/services/transformer.ts
import { PosOrder, PosOrderItem, KdsOrder, KdsOrderItem, OrderPriority } from '../types/contracts';
import { v4 as uuidv4 } from 'uuid';

/**
 * Transforms a POS order into the internal KDS representation.
 * Priority is derived from total estimated prep time (simple heuristic).
 */
export function transformPosToKds(posOrder: PosOrder): KdsOrder {
  const totalPrepSeconds = posOrder.items.reduce(
    (sum, it) => sum + it.prepTimeSeconds * it.quantity,
    0
  );

  let priority: OrderPriority;
  if (totalPrepSeconds <= 30) priority = 'LOW';
  else if (totalPrepSeconds <= 60) priority = 'NORMAL';
  else if (totalPrepSeconds <= 120) priority = 'HIGH';
  else priority = 'URGENT';

  const kdsItems: KdsOrderItem[] = posOrder.items.map((it) => ({
    id: it.id,
    name: it.name,
    quantity: it.quantity,
    modifiers: [...it.modifiers],
    station: it.station,
    prepTimeSeconds: it.prepTimeSeconds,
    startedAt: undefined,
    completedAt: undefined,
  }));

  return {
    id: uuidv4(),
    posOrderId: posOrder.posOrderId,
    status: 'PENDING',
    priority,
    items: kdsItems,
    receivedAt: new Date().toISOString(),
    completedAt: undefined,
  };
}
```

