// src/services/idempotencyStore.ts
import { RedisClientType } from 'redis';

/**
 * Very thin wrapper around Redis SET NX EX for idempotency keys.
 * In a real system you would also store the response payload.
 */
export class IdempotencyStore {
  private readonly client: RedisClientType;
  private readonly ttlSeconds: number;

  constructor(redisClient: RedisClientType, ttlSeconds = 3600) {
    this.client = redisClient;
    this.ttlSeconds = ttlSeconds;
  }

  /**
   * Returns true if the key was set (i.e. first attempt), false if already present.
   */
  async tryConsume(key: string): Promise<boolean> {
    const result = await this.client.set(
      key,
      '1',
      { NX: true, EX: this.ttlSeconds }
    );
    return result === 'OK';
  }
}
