#### 4.4 The Spec (`cypress/e2e/kds.spec.cy.js`)

```js
// cypress/e2e/kds.spec.cy.js
/// <reference types="cypress" />

describe('KDS UI – Order Propagation & Error Handling', () => {
  const testOrder = {
    posOrderId: 'ORD-TEST-001',
    createdAt: new Date().toISOString(),
    items: [
      {
        id: 'i1',
        name: 'Cheeseburger',
        quantity: 1,
        modifiers: ['No Onions'],
        station: 'GRILL',
        prepTimeSeconds: 30,
      },
      {
        id: 'i2',
        name: 'Fries',
        quantity: 1,
        modifiers: [],
        station: 'FRYER',
        prepTimeSeconds: 90,
      },
    ],
  };

  beforeEach(() => {
    // Reset the board before each test – assumes a test‑only endpoint
    cy.request('POST', '/test/reset');
    // Visit the KDS board
    cy.visit('/');
  });

  it('displays a new order within 150ms average latency', () => {
    // We'll run the sync 5 times and assert the average latency ≤150ms
    const latencies = [];

    for (let i = 0; i < 5; i++) {
      const start = Date.now();
      cy.posSync({ ...testOrder, posOrderId: `${testOrder.posOrderId}-${i}` })
        .its('duration')
        .then((durationMs) => {
          latencies.push(durationMs);
          // Wait for UI to reflect the order (should be <150ms total)
          cy.waitForOrder(`${testOrder.posOrderId}-${i}`, { timeout: 200 });
        });
    }

    // After all requests, compute average and assert
    cy.wrap(latencies).then((arr) => {
      const avg = arr.reduce((a, b) => a + b, 0) / arr.length;
      expect(avg).to.be.lte(150, `Average latency ${avg}ms should be ≤150ms`);
    });
  });

  it('transitions order status from PENDING → PREPARING → READY', () => {
    cy.posSync(testOrder);
    cy.waitForOrder(testOrder.posOrderId);
    cy.assertOrderStatus(testOrder.posOrderId, 'PENDING');

    // Simulate kitchen staff starting work – via a test endpoint
    cy.request('POST', `/test/start/${testOrder.posOrderId}`);
    cy.assertOrderStatus(testOrder.posOrderId, 'PREPARING');

    // Simulate completion
    cy.request('POST', `/test/complete/${testOrder.posOrderId}`);
    cy.assertOrderStatus(testOrder.posOrderId, 'READY');
  });

  it('shows an error toast when the KDS API returns 500 and does not corrupt UI', () => {
    // Force the backend sync endpoint to return 500 for this specific orderId
    cy.request('POST', '/test/fail-sync', {
      posOrderId: testOrder.posOrderId,
      statusCode: 500,
    });

    cy.posSync(testOrder).then((resp) => {
      expect(resp.status).to.eq(500);
    });

    // UI should display an error toast
    cy.get('[data-cy="toast-error"]')
      .should('contain', 'Failed to sync order')
      .and('be.visible');

    // Order row must NOT appear (idempotency prevents phantom rows)
    cy.get(`[data-cy="order-row"][data-pos-id="${testOrder.posOrderId}"]`)
      .should('not.exist');
  });
});
```

