### 5. k6 Performance Script (`tests/performance/orderPropagation.k6.js`)

This script simulates a realistic POS‑to‑KDS load, measures **end‑to‑end latency** (time from POS sync request to the moment the order appears in the KDS UI via a lightweight polling endpoint), and asserts that the **average latency ≤150 ms**.

```js
// tests/performance/orderPropagation.k6.js
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Trend } from 'k6/metrics';

// Custom metric for average latency
const latencyTrend = new Trend('order_propagation_latency');

// Configuration – can be overridden via ENV or CLI
export const options = {
  stages: [
    { duration: '2m', target: 20 },   // ramp‑up to 20 VUs
    { duration: '3m', target: 20 },   // steady load
    { duration: '2m', target: 0 },    // ramp‑down
  ],
  thresholds: {
    // Primary acceptance criterion: average latency ≤150ms
    'order_propagation_latency': ['avg<150'],
    // Optional secondary guard: 95th percentile <250ms (helps catch spikes)
    'order_propagation_latency': ['p(95)<250'],
    // Ensure HTTP errors stay under 1%
    'errors': ['rate<0.01'],
  },
};

/**
 * Generates a realistic POS order payload.
 * `vu` and `iter` are used to make each order unique.
 */
function makeOrder(vu, iter) {
  const posId = `PERF-VU${vu}-ITER${iter}-${Date.now()}`;
  return {
    posOrderId: posId,
    createdAt: new Date().toISOString(),
    items: [
      {
        id: `item-${vu}-${iter}-A`,
        name: 'Burger',
        quantity: Math.floor(Math.random() * 3) + 1,
        modifiers: Math.random() > 0.5 ? ['No Pickles'] : [],
        station: 'GRILL',
        prepTimeSeconds: 30,
      },
      {
        id: `item-${vu}-${iter}-B`,
        name: 'Fries',
        quantity: Math.floor(Math.random() * 2) + 1,
        modifiers: [],
        station: 'FRYER',
        prepTimeSeconds: 90,
      },
    ],
  };
}

/**
 * Helper: polls a lightweight KDS endpoint that returns the timestamp
 * when an order with a given posOrderId was last seen in memory.
 * Returns the delta (now - orderReceivedAt) in ms.
 */
function pollOrderLatency(posOrderId, maxAttempts = 12, intervalMs = 250) {
  for (let i = 0; i < maxAttempts; i++) {
    const res = http.get(`http://backend:3000/api/kds/order-timestamp/${posOrderId}`);
    if (res.status === 200) {
      const payload = JSON.parse(res.body);
      const receivedAt = new Date(payload.receivedAt).getTime();
      const now = Date.now();
      return now - receivedAt; // latency in ms
    }
    sleep(intervalMs / 1000); // k6 sleep expects seconds
  }
  // If we get here, the order never appeared – treat as a high latency failure
  return 9999;
}

export default function () {
  const vu = __VU;
  const iter = __ITER;

  const order = makeOrder(vu, iter);
  const startTime = Date.now();

  // 1️⃣ POS → KDS sync (the call we want to measure)
  const syncResp = http.post(
    'http://backend:3000/api/pos/sync',
    JSON.stringify(order),
    {
      headers: { 'Content-Type': 'application/json' },
      timeout: '10s',
    }
  );

  // Basic validation – we expect a 202 Accepted (async processing)
  check(syncResp, {
    'sync status is 202': (r) => r.status === 202,
  });

  if (syncResp.status !== 202) {
    // Record a failure for the error rate threshold
    latencyTrend.add(9999); // large value to push avg up
    return;
  }

  // 2️⃣ Poll until we see the order in KDS (or timeout)
  const latencyMs = pollOrderLatency(order.posOrderId);
  latencyTrend.add(latencyMs);

  // Optional: think time between iterations to simulate realistic pacing
  sleep(1);
}
```

**Explanation of the script**

| Step | What it does | Why it matters |
|------|--------------|----------------|
| `makeOrder` | Generates a unique POS order with random quantities/modifiers. | Prevents caching/collisions and mimics real‑world variety. |
| `http.post` to `/api/pos/sync` | Triggers the POS‑→‑KDS integration layer (the same code path unit‑tested). | Measures the latency we care about. |
| `pollOrderLatency` | Calls a lightweight backend endpoint (`/api/kds/order-timestamp/:id`) that returns the timestamp when the KDS persisted the order. Loops up to ~3 s (12×250 ms). | Gives us an **end‑to‑end** measurement (network + processing + UI‑update simulation). |
| `latencyTrend` | Custom k6 metric that feeds into thresholds. | Allows us to assert `avg<150`. |
| `options.thresholds` | Enforces the acceptance criteria and adds a secondary p95 guard. | Guarantees the performance gate in CI. |

> The script assumes a **backend service** running on `http://backend:3000` (see CI workflow). Adjust host/port if your Docker compose uses different names.

