## 1. EXACT COMPONENT & INTERFACE SPECIFICATIONS

### 1.1 Core Data Models (`src/types/kds.ts`)

```typescript
// src/types/kds.ts
export type OrderStatus = 'PENDING' | 'PREPARING' | 'READY' | 'HELD' | 'CANCELLED' | 'COMPLETED';
export type OrderPriority = 'LOW' | 'NORMAL' | 'HIGH' | 'URGENT';

export interface OrderItem {
  id: string;
  name: string;
  quantity: number;
  modifiers: string[]; // e.g., ["No Onions", "Extra Cheese"]
  station: 'GRILL' | 'FRYER' | 'SALAD' | 'DESSERT' | 'BAR';
  prepTimeSeconds: number; // Estimated prep time for *this item*
  startedAt?: string; // ISO Timestamp
  completedAt?: string;
}

export interface KDSOrder {
  id: string; // UUID
  posOrderId: string; // Human readable ID from POS (e.g., "ORD-1024")
  status: OrderStatus;
  priority: OrderPriority;
  orderType: 'DINE_IN' | 'TAKEOUT' | 'DELIVERY' | 'DRIVE_THRU';
  tableNumber?: string;
  items: OrderItem[];
  createdAt: string; // ISO Timestamp
  updatedAt: string; // ISO Timestamp
  estimatedReadyAt?: string; // ISO Timestamp (Calculated server-side)
  totalPrepTimeSeconds: number; // Sum of active items
  source: 'POS' | 'KIOSK' | 'MOBILE';
}

export interface KDSCommandPayload {
  orderId: string;
  action: 'START' | 'HOLD' | 'MARK_READY' | 'CANCEL' | 'RECALL' | 'BUMP';
  itemIds?: string[]; // Optional: specific items, otherwise whole order
  userId: string; // Kitchen staff ID
  timestamp: string; // ISO Timestamp
}

export interface WebSocketMessage<T = unknown> {
  event: 'ORDER_CREATED' | 'ORDER_UPDATED' | 'ORDER_DELETED' | 'STATUS_CHANGED' | 'HEARTBEAT' | 'SYNC_COMPLETE';
  payload: T;
  timestamp: string;
}
```

### 1.2 Hook Contract (`src/hooks/useOrdersWebSocket.ts`)

**Return Type:** `UseOrdersWebSocketReturn` (Object, **NOT Array**)

```typescript
// src/hooks/useOrdersWebSocket.ts
import { KDSOrder, KDSCommandPayload, OrderStatus } from '../types/kds';

export interface UseOrdersWebSocketReturn {
  /** Map of Order ID -> KDSOrder for O(1) lookup */
  orders: Map<string, KDSOrder>; 
  /** Array derived from Map for easy rendering (sorted by priority/age) */
  ordersList: KDSOrder[]; 
  /** Current connection state */
  connectionStatus: 'CONNECTING' | 'CONNECTED' | 'DISCONNECTED' | 'ERROR';
  /** Optimistic UI update / Server command dispatch */
  sendCommand: (payload: KDSCommandPayload) => Promise<void>;
  /** Manual reconnect trigger */
  reconnect: () => void;
}
```

### 1.3 Component Specifications

#### A. `OrderCard` (`src/components/OrderCard.tsx`)
**Props:**
```typescript
interface OrderCardProps {
  order: KDSOrder;
  onAction: (action: KDSCommandPayload['action'], itemIds?: string[]) => void;
  compact?: boolean; // For mobile/dense views
}
```
**Visual Spec:**
*   **Header:** `posOrderId` (Large), `orderType` Badge (Color: DINE_IN=Blue, TAKEOUT=Orange, DELIVERY=Green, DRIVE_THRU=Purple), `priority` Indicator (Left border: LOW=Grey, NORMAL=Blue, HIGH=Orange, URGENT=Red Pulse Animation).
*   **Meta Row:** Table # / Driver Name, Timer (Countdown to `estimatedReadyAt` or Count-up from `createdAt`), Station Icons (Grid of active stations).
*   **Body:** Item List (Name x Qty, Modifiers chips, Item Status Badge).
*   **Footer Actions:** 
    *   `PREPARING` -> [Start Prep] (Primary), [Hold] (Secondary)
    *   `PREPARING` (Partial) -> [Mark Items Ready] (Primary), [Hold] 
    *   `READY` -> [Complete/Handoff] (Success), [Recall] (Ghost)
    *   `HELD` -> [Resume] (Primary), [Cancel] (Error)
    *   All -> [Cancel] (Error, Confirm Modal)

#### B. `KDSHeader` (`src/components/KDSHeader.tsx`)
**Props:**
```typescript
interface KDSHeaderProps {
  stationFilter: string[]; // e.g., ['GRILL', 'FRYER']
  onStationFilterChange: (stations: string[]) => void;
  connectionStatus: UseOrdersWebSocketReturn['connectionStatus'];
  orderCounts: Record<OrderStatus, number>;
}
```

#### C. `KDSBoard` (`src/pages/KDSBoard.tsx` - Main Container)
*   Orchestrates `useOrdersWebSocket`.
*   Manages Station Filter State.
*   Renders Virtualized List (`@tanstack/react-virtual`) of `OrderCard`s grouped by Status Columns (Kanban) OR Single Priority List (Configurable).
*   **Accessibility:** `role="region" aria-live="polite"` for order updates.

