## 3. ROBUST TESTING & MOCKING STRATEGY

### 3.1 Architecture: MSW + Vitest + JSDOM (Happy DOM)
*   **No `jest`**, use **`vitest`** (Native ESM, faster, Vite aligned).
*   **Environment:** `jsdom` (Configured in `vitest.config.ts`).
*   **Mocking WebSocket:** **DO NOT** mock `socket.io-client` internals directly. Mock the **Network Layer** using **MSW (Mock Service Worker)** for HTTP REST *and* a **Mock WebSocket Server** (`ws` library) spun up in `globalSetup` or via `vi.hoisted` for the `socket.io` handshake/transport.
*   **Simpler Alternative (Unit Test Hook Only):** Mock `socket.io-client` `io` export using `vi.mock` to return a **controllable Mock Socket Instance**. This is faster and less flaky for hook logic.

### 3.2 Mock Socket Implementation (`tests/mocks/socket.ts`)

```typescript
// tests/mocks/socket.ts
import { vi, type MockInstance } from 'vitest';
import { Server as MockSocketServer, Socket as MockSocket } from 'mock-socket'; // Use 'mock-socket' lib OR manual implementation below

// --- MANUAL MINIMAL MOCK (Zero Deps, Maximum Control) ---
export type MockSocketEventMap = {
  connect: () => void;
  disconnect: (reason: string) => void;
  connect_error: (err: Error) => void;
  [key: string]: (...args: unknown[]) => void;
};

export class ControllableMockSocket {
  public listeners: Map<string, Function[]> = new Map();
  public connected = false;
  public id = 'mock-socket-id';

  on(event: string, cb: Function) {
    if (!this.listeners.has(event)) this.listeners.set(event, []);
    this.listeners.get(event)!.push(cb);
  }
  off(event: string, cb?: Function) {
    if (!cb) { this.listeners.delete(event); return; }
    this.listeners.set(event, this.listeners.get(event)?.filter(f => f !== cb) || []);
  }
  emit(event: string, ...args: unknown[]) {
    this.listeners.get(event)?.forEach(cb => cb(...args));
  }

  // Socket.io Client API Surface
  connect() { 
    this.connected = true; 
    setTimeout(() => this.emit('connect'), 0); 
  }
  disconnect() { 
    this.connected = false; 
    this.emit('disconnect', 'client disconnect'); 
  }
  send(_buffer: unknown[]) {} // No-op
  close() { this.disconnect(); }
}

// Global registry for tests to grab the instance
let currentMockSocket: ControllableMockSocket | null = null;

export const getMockSocket = () => currentMockSocket;

export const mockSocketIoClient = () => {
  return vi.mock('socket.io-client', () => ({
    io: vi.fn((_url, _opts) => {
      currentMockSocket = new ControllableMockSocket();
      return currentMockSocket;
    }),
    default: { io: vi.fn() }
  }));
};
```

