```typescript
import axios, { 
  AxiosInstance, 
  AxiosError, 
  InternalAxiosRequestConfig, 
  AxiosRequestConfig 
} from 'axios';
import { config } from '../config';
import pino from 'pino';

const logger = pino({ name: 'retry-middleware' });

/**
 * Calculates exponential backoff with jitter.
 */
export function calculateBackoff(attempt: number, baseDelayMs: number): number {
  const exponentialDelay = baseDelayMs * Math.pow(2, attempt);
  const jitter = Math.random() * 0.3 * exponentialDelay;
  return Math.floor(exponentialDelay + jitter);
}

/**
 * Determines if an error is retryable.
 */
export function isRetryableError(error: AxiosError, isIdempotent: boolean): boolean {
  if (!error.response) return true; // Network error

  const status = error.response.status;

  if (status === 429) return true; // Rate limit
  if (status >= 500) return true;  // Server errors

  // 409 Conflict: Retry ONLY if idempotent
  if (status === 409) return isIdempotent;

  return false; // 400, 401, 403, 404, 422, etc.
}

/**
 * Axios Request Interceptor: Attaches KDS metadata to config.
 */
export function attachKdsMetadataInterceptor(instance: AxiosInstance): number {
  return instance.interceptors.request.use((config: InternalAxiosRequestConfig) => {
    if (config.kds?.idempotencyKey) {
      config.headers['Idempotency-Key'] = config.kds.idempotencyKey;
      config.headers['X-POS-Event-ID'] = config.kds.posEventId;
    }
    config.headers['X-KDS-Source'] = 'POS-INTEGRATION-LAYER';
    return config;
  });
}

/**
 * Axios Response Interceptor: Handles Retries & Dead Letter Queue routing.
 */
export function attachRetryInterceptor(
  instance: AxiosInstance,
  dlqHandler: (entry: Omit<DeadLetterEntry, 'id' | 'createdAt'>) => Promise<void>
): number {
  return instance.interceptors.response.use(
    (response) => response,
    async (error: AxiosError) => {
      const originalConfig = error.config as InternalAxiosRequestConfig | undefined;
      if (!originalConfig) return Promise.reject(error);

      const kdsMeta = originalConfig.kds;
      const isIdempotent = kdsMeta?.isIdempotent ?? false;
      const posEventId = kdsMeta?.posEventId ?? 'unknown';
      const attempt = (originalConfig.headers['X-Retry-Attempt'] as number) || 0;
      const maxRetries = config.kds.maxRetries;

      if (!isRetryableError(error, isIdempotent) || attempt >= maxRetries) {
        logger.error({
          posEventId,
          attempt: attempt + 1,
          maxRetries,
          status: error.response?.status,
          message: 'Max retries exceeded or non-retryable error. Sending to DLQ.',
        }, 'Request failed permanently');

        await dlqHandler({
          payload: originalConfig.data as PosOrderEvent,
          error: error.message,
          attempts: attempt + 1,
          lastAttempt: new Date().toISOString(),
        });

        return Promise.reject(error);
      }

      const delay = calculateBackoff(attempt, config.kds.retryBaseDelayMs);
      logger.warn({
        posEventId,
        attempt: attempt + 1,
        delayMs: delay,
        status: error.response?.status,
      }, 'Retrying request...');

      await new Promise(resolve => setTimeout(resolve, delay));

      originalConfig.headers['X-Retry-Attempt'] = attempt + 1;
      return instance.request(originalConfig);
    }
  );
}
```

