### 2.5 k6 Script Contract (`performance/kds-load-test.js`)
**Must export `thresholds` object exactly as below for Gate Job to parse.**

```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate, Trend } from 'k6/metrics';

// Custom Metrics
export const orderPropagationLatency = new Trend('order_propagation_latency_ms');
export const errorRate = new Rate('errors');

export const options = {
  scenarios: {
    sync_latency: {
      executor: 'constant-arrival-rate',
      rate: 50, // 50 orders/sec
      timeUnit: '1s',
      duration: '2m',
      preAllocatedVUs: 50,
      maxVUs: 100,
    },
  },
  thresholds: {
    // ACCEPTANCE CRITERIA: ≤150ms average latency
    'order_propagation_latency_ms': ['avg<150', 'p(95)<300'],
    'http_req_duration': ['p(95)<500'],
    'errors': ['rate<0.01'], // <1% error rate
    'checks': ['rate>0.99'],
  },
  // Ensure summary JSON output for artifact
  summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(90)', 'p(95)', 'p(99)'],
};

const BASE_URL = __ENV.KDS_API_URL || 'http://localhost:4000';
const POS_URL = __ENV.POS_API_URL || 'http://localhost:4001';

export default function () {
  const payload = JSON.stringify({
    orderId: `ord_${__VU}_${__ITER}`,
    items: [{ sku: 'BURGER', qty: 1, mods: ['NO_PICKLES'] }],
    timestamp: new Date().toISOString(),
  });

  const params = { headers: { 'Content-Type': 'application/json' } };

  // 1. POS Creates Order
  const posRes = http.post(`${POS_URL}/orders`, payload, params);
  const posCheck = check(posRes, { 'POS Create 201': (r) => r.status === 201 });
  errorRate.add(!posCheck);

  // 2. Measure KDS Propagation (Polling or WebSocket)
  // Assuming REST Poll for simplicity in CI contract
  let kdsRes;
  let latency = 0;
  const start = new Date();

  // Poll KDS until order appears (max 2s)
  for (let i = 0; i < 20; i++) {
    kdsRes = http.get(`${BASE_URL}/kds/orders/${payload.orderId}`, params);
    if (kdsRes.status === 200) {
      latency = new Date() - start;
      break;
    }
    sleep(0.1);
  }

  const kdsCheck = check(kdsRes, { 'KDS Sync 200': (r) => r.status === 200 });
  errorRate.add(!kdsCheck);

  if (latency > 0) {
    orderPropagationLatency.add(latency);
  } else {
    errorRate.add(true); // Timeout
  }

  sleep(0.5);
}

export function handleSummary(data) {
  // CRITICAL: Write threshold status file for Gate Job
  const thresholdStatus = Object.values(data.metrics).some(m => m.thresholds && Object.values(m.thresholds).some(t => !t.ok)) ? 'FAIL' : 'PASS';

  // This file is read by the 'performance-gate' job to set exit code
  // Note: k6 cannot write files directly in cloud mode, but in `k6 run` local mode it can via JS.
  // Workaround: Use `echo` in CI step after k6 runs. See Pipeline Spec.
  return {
    'stdout': JSON.stringify(data, null, 2), // For k6-summary.json artifact
    'k6-junit.xml': jUnit(data), // Requires custom jUnit generator or use `k6-junit` npm pkg wrapper
  };
}

// Minimal JUnit generator inline (or use `k6-junit` package)
function jUnit(data) { /* ... implementation omitted for brevity, use npm pkg `k6-junit` in CI step */ return ''; }
