## 3. Robust Testing & Mocking Strategy (Backend Unit/Integration)

**Goal:** Zero flakiness, no JSDOM, pure Node.js `testEnvironment: 'node'`.

### 3.1 Architecture: MSW (Mock Service Worker) + `msw/node`
Intercept `fetch`/`axios` at the **network level**, not module level. Works in Jest `node` env.

#### `packages/backend/jest.setup.ts` (Mandatory Entry Point)
```typescript
// 1. Polyfills (if needed for TextEncoder, etc.)
import { TextEncoder, TextDecoder } from 'util';
global.TextEncoder = TextEncoder;
global.TextDecoder = TextDecoder;

// 2. MSW Server Setup
import { setupServer } from 'msw/node';
import { handlers } from './test-utils/handlers'; // Centralized handlers

export const server = setupServer(...handlers);

// 3. Global Lifecycle
beforeAll(() => server.listen({ onUnhandledRequest: 'error' })); // Fail on unmocked requests
afterEach(() => server.resetHandlers());
afterAll(() => server.close());
```

#### `packages/backend/test-utils/handlers.ts` (The Contract)
```typescript
import { http, HttpResponse } from 'msw';
import { posMockHandlers } from './pos-mock.handlers';
import { kdsMockHandlers } from './kds-mock.handlers';

// Export array spread for setupServer
export const handlers = [
  ...posMockHandlers,
  ...kdsMockHandlers,
  // Fallback catch-all to detect leaks
  http.all('*', () => {
    throw new Error(`Unhandled Request in Test: ${new Error().stack}`);
  }),
];
```

#### `packages/backend/test-utils/pos-mock.handlers.ts` (Example)
```typescript
import { http, HttpResponse, delay } from 'msw';

export const posMockHandlers = [
  http.post('http://pos-mock:4001/orders', async ({ request }) => {
    await delay(10); // Simulate network latency
    const body = await request.json();
    // Validate contract
    if (!body.orderId || !body.items) {
      return HttpResponse.json({ error: 'Invalid Order Schema' }, { status: 400 });
    }
    return HttpResponse.json({ success: true, orderId: body.orderId }, { status: 201 });
  }),

  http.get('http://pos-mock:4001/orders/:id', ({ params }) => {
    return HttpResponse.json({ id: params.id, status: 'SENT_TO_KDS' });
  }),
];
```

### 3.2 Test File Pattern (`*.spec.ts`)
```typescript
// src/modules/orders/orders.service.spec.ts
import { OrdersService } from './orders.service';
import { server, http, HttpResponse } from '../test-utils/handlers'; // Import server for override

describe('OrdersService - POS/KDS Sync', () => {
  let service: OrdersService;

  beforeEach(() => {
    service = new OrdersService(); // Injects HttpClient configured for test env
  });

  it('propagates order to KDS within 150ms (unit mock)', async () => {
    // Override specific handler for latency simulation
    server.use(
      http.get('http://kds-mock:4002/kds/orders/:id', async () => {
        await new Promise(r => setTimeout(r, 50)); // Simulate 50ms internal latency
        return HttpResponse.json({ synced: true });
      })
    );

    const start = performance.now();
    await service.createAndSync({ orderId: 'test-1', items: [] });
    const duration = performance.now() - start;

    expect(duration).toBeLessThan(150); // Unit level assertion
  });
});
